backend/bot/perf.py:
"""Paper P&L tracking: how the Auto bot (and, to compare, manual Signal Lab paper trades and the AI agent's book) is doing.
PAPER ONLY: reads the ledgers, never places an order.

Sources
  bot     Signal Lab ledger trades opened by the PC Auto bot (ids kept in .lab/bot_state.json)
  manual  Signal Lab ledger trades you opened yourself ("Paper trade" button)
  agent   the AI agent's own paper book (agent_trades, mode = paper)
  all     everything above

Money is per currency (INR for India / MCX, USD for crypto / US / forex) and never added across currencies; R
(P&L after costs / the initial stop risk) is the cross-currency yardstick. Closed P&L is after costs. Open P&L =
what is already booked at T1/T2 plus the rest marked at the latest price, BEFORE exit costs (an estimate).
Days and weeks are Indian time (IST); a week starts Monday.

build() is pure (rows in, report out) so it can be tested without a market feed; report() gathers the rows.
"""
from __future__ import annotations

import datetime as dt
import json
import time

IST = dt.timezone(dt.timedelta(hours=5, minutes=30))
SOURCES = ("bot", "manual", "agent", "all")
_MARKS: dict[str, tuple[float, float]] = {}          # symbol -> (time, last price): one candle call per symbol per 20 s
MARK_TTL = 20


def _j(s, default):
    try:
        return json.loads(s) if isinstance(s, str) else (s if s is not None else default)
    except ValueError:
        return default


# ---------------------------------------------------------------- rows from the ledgers
def norm_lab(r: dict, bot_ids: dict) -> dict:
    p = _j(r.get("payload"), {})
    b = bot_ids.get(str(r["id"]))
    return {"src": "bot" if b else "manual", "id": r["id"], "key": f"L{r['id']}", "symbol": r["symbol"], "market": r["market"],
            "side": r["side"], "qty": r["qty"] or 0, "entry": r["entry"], "stop": r["stop"], "targets": _j(r.get("targets"), []),
            "opened_at": r["opened_at"], "closed_at": r["closed_at"], "exit": r.get("exit"), "exit_reason": r.get("exit_reason"),
            "status": r["status"], "currency": r["currency"] or "USD", "gross": r.get("gross"), "costs": r.get("costs"),
            "pnl": r.get("pnl"), "r": r.get("r_result"), "strategy": (b or {}).get("name") or p.get("strategy") or "",
            "strategy_id": p.get("strategy") or "", "tf": p.get("tf") or (b or {}).get("tf") or "", "hit": p.get("hit") or [],
            "left": p.get("left", 1.0), "booked": p.get("realised", 0.0), "stop_now": p.get("stop_now", r["stop"])}


def norm_agent(r: dict) -> dict:
    p = _j(r.get("payload"), {})
    return {"src": "agent", "id": r["id"], "key": f"A{r['id']}", "symbol": r["symbol"], "market": r["market"], "side": r["side"],
            "qty": r["qty"] or 0, "entry": r["entry"], "stop": r["stop"], "targets": _j(r.get("targets"), []),
            "opened_at": r["opened_at"], "closed_at": r["closed_at"], "exit": r.get("exit"), "exit_reason": r.get("exit_reason"),
            "status": r["status"], "currency": r["currency"] or "USD", "gross": r.get("gross"), "costs": r.get("costs"),
            "pnl": r.get("pnl"), "r": r.get("r_result"), "strategy": r.get("strategy") or "", "strategy_id": r.get("strategy") or "",
            "tf": r.get("tf") or "", "hit": p.get("hit") or [], "left": p.get("left", 1.0), "booked": p.get("realised", 0.0),
            "stop_now": p.get("stop_now", r["stop"])}


# ---------------------------------------------------------------- the maths
def _day(t: int) -> str:
    return dt.datetime.fromtimestamp(t, IST).strftime("%Y-%m-%d")


def _starts(now: float) -> dict:
    d = dt.datetime.fromtimestamp(now, IST).replace(hour=0, minute=0, second=0, microsecond=0)
    return {"today": d.timestamp(), "week": (d - dt.timedelta(days=d.weekday())).timestamp(),
            "month": d.replace(day=1).timestamp(), "all": 0}


def mark_open(t: dict, px: float | None) -> dict:
    """Open trade: booked part + the rest at `px`, in money and R (before exit costs)."""
    d = 1 if t["side"] == "LONG" else -1
    risk = abs((t["entry"] or 0) - (t["stop"] or 0)) * t["qty"]
    if px is None:
        return {**t, "price": None, "upnl": None, "ur": None, "risk_money": round(risk, 2)}
    money = (t["booked"] + t["left"] * (px - t["entry"]) * d) * t["qty"]
    at_risk = max(0.0, (t["entry"] - t["stop_now"]) * d * t["left"] * t["qty"]) if t.get("stop_now") is not None else risk
    return {**t, "price": px, "upnl": round(money, 2), "ur": round(money / risk, 3) if risk else 0,
            "risk_money": round(risk, 2), "open_risk": round(at_risk, 2)}


def stats(rows: list[dict]) -> dict:
    """Closed trades, one currency (money) or mixed (R only)."""
    n = len(rows)
    if not n:
        return {"trades": 0}
    pn = [r["pnl"] or 0 for r in rows]
    rs = [r["r"] or 0 for r in rows]
    w = [x for x in pn if x > 0]
    lo = [x for x in pn if x <= 0]
    eq = peak = mdd = 0.0
    for x in pn:
        eq += x
        peak = max(peak, eq)
        mdd = min(mdd, eq - peak)
    best_w = best_l = run = 0                               # streaks in time order: +n wins in a row, -n losses
    for x in pn:
        if x > 0:
            run = run + 1 if run > 0 else 1
        else:
            run = run - 1 if run < 0 else -1
        best_w, best_l = max(best_w, run), min(best_l, run)
    cur = run
    gw, gl = sum(w), -sum(lo)
    return {"trades": n, "wins": len(w), "losses": len(lo), "win_rate": round(100 * len(w) / n, 1),
            "pnl": round(sum(pn), 2), "gross": round(sum(r["gross"] or 0 for r in rows), 2), "costs": round(sum(r["costs"] or 0 for r in rows), 2),
            "avg_win": round(gw / len(w), 2) if w else 0, "avg_loss": round(-gl / len(lo), 2) if lo else 0,
            "profit_factor": round(gw / gl, 2) if gl else (None if not gw else 999),
            "avg_r": round(sum(rs) / n, 3), "total_r": round(sum(rs), 2),
            "best": round(max(pn), 2), "worst": round(min(pn), 2), "max_dd": round(mdd, 2),
            "streak": cur, "best_streak": best_w, "worst_streak": -best_l}


def _group(rows: list[dict], key) -> list[dict]:
    g: dict = {}
    for r in rows:
        g.setdefault(key(r), []).append(r)
    out = []
    for k, v in g.items():
        by_cur = {c: round(sum(x["pnl"] or 0 for x in v if x["currency"] == c), 2) for c in sorted({x["currency"] for x in v})}
        w = sum(1 for x in v if (x["pnl"] or 0) > 0)
        out.append({"key": k, "trades": len(v), "win_rate": round(100 * w / len(v), 1), "pnl": by_cur,
                    "avg_r": round(sum(x["r"] or 0 for x in v) / len(v), 3), "total_r": round(sum(x["r"] or 0 for x in v), 2)})
    return sorted(out, key=lambda x: -x["total_r"])


def build(rows: list[dict], marks: dict[str, float | None], now: float | None = None, capital: dict | None = None, source: str = "bot") -> dict:
    now = now or time.time()
    capital = capital or {}
    closed = sorted([r for r in rows if r["status"] == "closed" and r.get("closed_at")], key=lambda r: r["closed_at"])
    opened = [mark_open(r, marks.get(r["symbol"])) for r in rows if r["status"] != "closed"]
    starts = _starts(now)
    curs = sorted({r["currency"] for r in rows}) or ["INR"]
    by_cur = {}
    for c in curs:
        cc = [r for r in closed if r["currency"] == c]
        oc = [r for r in opened if r["currency"] == c]
        periods = {}
        for p, t0 in starts.items():
            s = stats([r for r in cc if r["closed_at"] >= t0])
            periods[p] = {k: s.get(k, 0) for k in ("trades", "wins", "losses", "win_rate", "pnl", "costs", "total_r")}
        days: dict = {}
        for r in cc:
            d = days.setdefault(_day(r["closed_at"]), {"day": _day(r["closed_at"]), "pnl": 0.0, "trades": 0, "wins": 0, "r": 0.0})
            d["pnl"] += r["pnl"] or 0
            d["trades"] += 1
            d["wins"] += (r["pnl"] or 0) > 0
            d["r"] += r["r"] or 0
        cum, daily = 0.0, []
        for d in sorted(days.values(), key=lambda x: x["day"]):
            cum += d["pnl"]
            daily.append({**d, "pnl": round(d["pnl"], 2), "r": round(d["r"], 2), "cum": round(cum, 2)})
        cum, curve = 0.0, []
        for r in cc:
            cum += r["pnl"] or 0
            curve.append({"t": r["closed_at"], "cum": round(cum, 2), "key": r["key"]})
        upnl = [r["upnl"] for r in oc if r["upnl"] is not None]
        cap = capital.get(c)
        s = stats(cc)
        by_cur[c] = {"closed": s, "periods": periods, "daily": daily, "curve": curve, "capital": cap,
                     "return_pct": round(100 * s.get("pnl", 0) / cap, 2) if cap else None,
                     "open": {"trades": len(oc), "upnl": round(sum(upnl), 2) if upnl else 0, "unpriced": len(oc) - len(upnl),
                              "risk": round(sum(r.get("open_risk", r["risk_money"]) for r in oc), 2)},
                     "today_total": round(periods["today"]["pnl"] + (sum(upnl) if upnl else 0), 2)}
    return {"source": source, "generated": int(now), "currencies": curs, "by_currency": by_cur,
            "all_r": {k: v for k, v in stats(closed).items() if k in ("trades", "win_rate", "avg_r", "total_r")},
            "by_symbol": _group(closed, lambda r: r["symbol"]), "by_strategy": _group(closed, lambda r: r["strategy"] or "—"),
            "by_exit": _group(closed, lambda r: r["exit_reason"] or "—"), "by_side": _group(closed, lambda r: r["side"]),
            "by_source": _group(closed, lambda r: r["src"]) if source == "all" else [],
            "open": sorted(opened, key=lambda r: -r["opened_at"]),
            "trades": sorted(closed, key=lambda r: -r["closed_at"])[:500]}


# ---------------------------------------------------------------- gathering (needs the running app)
async def _price(symbol: str, market: str) -> float | None:
    from backend.lab import data as D
    hit = _MARKS.get(symbol)
    if hit and time.time() - hit[0] < MARK_TTL:
        return hit[1]
    try:
        bars, _ = await D.candles(symbol, "1m" if market != "YF" else "5m", 3)
        px = float(bars[-1].close)
    except Exception:                                     # noqa: BLE001 - no feed (e.g. FYERS logged out): leave it unpriced
        return hit[1] if hit else None
    _MARKS[symbol] = (time.time(), px)
    return px


def rows_for(source: str, bot_ids: dict) -> list[dict]:
    from backend.lab import store
    rows: list[dict] = []
    if source in ("bot", "manual", "all"):
        for r in store.q("SELECT * FROM trades ORDER BY id"):
            n = norm_lab(r, bot_ids)
            if source == "all" or n["src"] == source:
                rows.append(n)
    if source in ("agent", "all"):
        try:
            rows += [norm_agent(r) for r in store.q("SELECT * FROM agent_trades WHERE mode='paper' OR mode IS NULL ORDER BY id")]
        except Exception:                                 # noqa: BLE001 - agent tables not created yet
            pass
    return rows


async def report(source: str = "bot", bot_ids: dict | None = None) -> dict:
    from backend.lab import service as SV, protect as P
    if source not in SOURCES:
        source = "bot"
    try:
        await SV.paper_list()                              # walks open Lab trades forward first (T1/T2/stop)
    except Exception:                                     # noqa: BLE001
        pass
    rows = rows_for(source, bot_ids or {})
    marks = {}
    for r in rows:
        if r["status"] != "closed" and r["symbol"] not in marks:
            marks[r["symbol"]] = await _price(r["symbol"], r["market"])
    ps = P.settings()
    return build(rows, marks, capital={"INR": ps.get("capital_inr"), "USD": ps.get("capital_usd")}, source=source)

backend/brokers/fyers/client.py:
"""Phone build: FYERS data calls go through the browser's FYERS client (js/engine.js MM.FY.get), which holds the
token on this device. Same return shape as the PC's data_get.

Like the PC, every /history, /quotes and /options-chain-v3 request goes through the shared store (hist.py, the
PC's own file): one download serves every timeframe and every caller, updates only after a candle closes, and
stored candles are served when FYERS refuses (daily limit / network)."""
import json

from _bridge import js

from . import hist as _hist

_usage = {"used": 0, "cap": 5000, "t": 0.0}


async def _raw_get(path, params):
    return await js("fyGet", path, {k: ("" if v is None else v) for k, v in params.items()})


def _budget():
    return _usage["used"], _usage["cap"]


async def refresh_usage():
    """Today's FYERS request count on this device (kept by js/engine.js)."""
    try:
        u = await js("fyUsage")
        _usage.update(used=int(u.get("today") or 0), cap=int(u.get("per_day_cap") or 5000))
    except Exception:                                     # noqa: BLE001
        pass


STORE = _hist.Store(fetch=_raw_get, budget=_budget)


async def data_get(path, params):
    import time
    if time.time() - _usage["t"] > 60:
        _usage["t"] = time.time()
        await refresh_usage()
    if path == "/history":
        return await STORE.history(params)
    if path == "/quotes":
        return await STORE.quote(params)
    if path == "/options-chain-v3":
        return await STORE.chain(params)
    return await _raw_get(path, params)


_PER_DAY = 5000


def day_used():
    return _usage["used"]


def rate_status():
    return {"today": _usage["used"], "per_day_cap": _usage["cap"], "store": STORE.status()}

backend/brokers/fyers/hist.py:
"""Shared FYERS data store: every FYERS data request in MarketMiner goes through here, so one download serves every
page, the Signal Lab bot, the AI agent, the sweep and the Day Desk.

Why: the Standard (free) FYERS plan allows 5,000 data requests a day. Before this, each caller downloaded its own
copy (per timeframe, per candle count, every 10-120 s) and the day's budget was gone by early afternoon.

History (/history)
  * one BASE series per symbol: 5-minute candles serve 5/10/15/20/30/60/120/240-minute requests (resampled here,
    aligned to the session open 09:15 NSE/BSE, 09:00 MCX, the way FYERS builds them); 1-minute serves 1/2/3-minute;
    daily serves daily. Weekly/monthly are passed through.
  * the first request downloads the range asked for; later requests for older history fetch only the missing part;
    updates fetch only from the last stored day (one small request).
  * an update happens only right after a candle has CLOSED, at most once every MIN_REFRESH seconds per symbol
    (default 5 minutes; MARKETMINER_FYERS_MIN_REFRESH), never outside market hours once the session's final
    candles are in. The interval stretches as the day's budget is used (x2 at 40%, x4 at 70%, x10 at 85%).
    So a 5-minute chart gets every candle as it closes; the candle still forming is not polled (the live price
    stream will fill that in).
  * single flight: callers asking for the same symbol at the same moment share one request.
  * if FYERS refuses (daily limit, network), the stored candles are served (they are marked stale by the candle
    validator downstream) instead of an error, whenever there is something stored.
Quotes (/quotes): cached per symbol for QUOTE_AGE s; a batch is fetched only for the symbols not fresh.
Option chain: cached per request for CHAIN_AGE s.
Nothing here places orders.
"""
from __future__ import annotations

import asyncio
import datetime as dt
import os
import time
from typing import Any, Awaitable, Callable

IST = dt.timezone(dt.timedelta(hours=5, minutes=30))
MIN_REFRESH = float(os.getenv("MARKETMINER_FYERS_MIN_REFRESH", "300") or 300)   # seconds between updates of one symbol
CLOSE_GRACE = 4.0        # wait this long after a candle closes before fetching it
QUOTE_AGE = 5.0
CHAIN_AGE = 30.0
MAX_DAYS = {"1": 100, "5": 100, "D": 366}
BASE_OF = {"1": "1", "2": "1", "3": "1", "5": "5", "10": "5", "15": "5", "20": "5", "30": "5", "45": "5", "60": "5", "120": "5",
           "180": "5", "240": "5", "D": "D", "1D": "D"}

Fetch = Callable[[str, dict], Awaitable[dict]]


class Stats:
    def __init__(self):
        self.reset()

    def reset(self):
        self.day = dt.datetime.now(IST).date().isoformat()
        self.requests = 0          # asked of the store
        self.fetched = 0           # sent to FYERS
        self.stale_served = 0

    def roll(self):
        if self.day != dt.datetime.now(IST).date().isoformat():
            self.reset()


STATS = Stats()


def _anchor(symbol: str) -> int:
    """Session open in minutes after midnight IST."""
    return 540 if symbol.upper().startswith("MCX:") else 555


def _session(symbol: str) -> tuple[int, int]:
    s = symbol.upper()
    if s.startswith("MCX:"):
        return 540, 23 * 60 + 55
    return 555, 15 * 60 + 30


def market_open(symbol: str, now: float) -> bool:
    d = dt.datetime.fromtimestamp(now, IST)
    if d.weekday() >= 5:
        return False
    a, b = _session(symbol)
    m = d.hour * 60 + d.minute
    return a <= m < b + 2


def budget_factor(used: int, cap: int) -> float:
    f = used / cap if cap else 0
    return 1.0 if f < 0.4 else 2.0 if f < 0.7 else 4.0 if f < 0.85 else 10.0


def resample(rows: list[list], minutes: int, anchor: int) -> list[list]:
    """Intraday rows [t, o, h, l, c, v] -> `minutes` candles counted from the session open (IST)."""
    out: list[list] = []
    step = minutes * 60
    for r in rows:
        ist = int(r[0]) + 19800
        day = ist // 86400
        mins = (ist % 86400) // 60
        k = (mins - anchor) // minutes if mins >= anchor else -1 - (anchor - mins - 1) // minutes
        start = day * 86400 + anchor * 60 + k * step - 19800
        if out and out[-1][0] == start:
            o = out[-1]
            o[2] = max(o[2], r[2])
            o[3] = min(o[3], r[3])
            o[4] = r[4]
            o[5] = (o[5] or 0) + (r[5] or 0)
        else:
            out.append([start, r[1], r[2], r[3], r[4], r[5] or 0])
    return out


def _to_date(v: Any, fmt: str) -> dt.date:
    if str(fmt) == "0":
        return dt.datetime.fromtimestamp(int(float(v)), IST).date()
    return dt.date.fromisoformat(str(v)[:10])


class Series:
    def __init__(self, symbol: str, base: str, cont: str):
        self.symbol, self.base, self.cont = symbol, base, cont
        self.rows: list[list] = []
        self.cov_from: dt.date | None = None    # earliest day downloaded
        self.last_fetch = 0.0
        self.last_req = 0.0                    # when a caller last asked (the live feed follows these symbols)
        self.lock = asyncio.Lock()

    @property
    def step(self) -> int:
        return 86400 if self.base == "D" else int(self.base) * 60

    def merge(self, new: list[list]) -> None:
        if not new:
            return
        new = sorted(new, key=lambda r: r[0])
        if not self.rows or new[0][0] > self.rows[-1][0]:
            self.rows += new
            return
        if new[-1][0] < self.rows[0][0]:
            self.rows = new + self.rows
            return
        keep = {int(r[0]): r for r in self.rows}
        for r in new:
            keep[int(r[0])] = r
        self.rows = [keep[t] for t in sorted(keep)]

    def needs_update(self, now: float, factor: float) -> bool:
        if not self.rows:
            return True
        d = dt.datetime.fromtimestamp(now, IST)
        a, b = _session(self.symbol)
        close_ts = d.replace(hour=b // 60, minute=b % 60, second=0, microsecond=0).timestamp()
        if self.base == "D":
            if market_open(self.symbol, now):
                return now - self.last_fetch >= 900.0 * factor
            return d.weekday() < 5 and now >= close_ts + 60 and self.last_fetch < close_ts + 60
        if not market_open(self.symbol, now):
            # closed: one last update after the close (to get the final candles), then nothing until the next open
            if d.weekday() < 5 and now >= close_ts and self.last_fetch < close_ts + 60:
                return now - self.last_fetch >= 30
            return False
        # right after a candle closes, on a grid of max(candle, MIN_REFRESH) x budget factor: a 5-minute series is
        # updated a few seconds after every 5-minute close (every other close at 40% of the budget, ...)
        grid = max(self.step, MIN_REFRESH) * factor
        since = now % grid
        return since >= CLOSE_GRACE and self.last_fetch < now - since + CLOSE_GRACE

    def slice(self, a: dt.date, b: dt.date) -> list[list]:
        lo = dt.datetime.combine(a, dt.time(0), IST).timestamp()
        hi = dt.datetime.combine(b, dt.time(23, 59, 59), IST).timestamp()
        return [r for r in self.rows if lo <= r[0] <= hi]


class Store:
    def __init__(self, fetch: Fetch, budget: Callable[[], tuple[int, int]] = lambda: (0, 5000), clock: Callable[[], float] = time.time):
        self.fetch, self.budget, self.clock = fetch, budget, clock
        self.series: dict[tuple, Series] = {}
        self.quotes: dict[str, tuple[float, dict]] = {}
        self.chains: dict[tuple, tuple[float, dict]] = {}
        self.inflight: dict[tuple, asyncio.Future] = {}

    def _factor(self) -> float:
        used, cap = self.budget()
        return budget_factor(used, cap)

    async def _get_raw(self, params: dict) -> list[list]:
        STATS.fetched += 1
        p = await self.fetch("/history", params)
        return [list(r) for r in (p.get("candles") or [])]

    async def _download(self, s: Series, a: dt.date, b: dt.date) -> list[list]:
        span = MAX_DAYS.get(s.base, 100)
        out, cur = [], a
        while cur <= b:
            end = min(b, cur + dt.timedelta(days=span - 1))
            out += await self._get_raw({"symbol": s.symbol, "resolution": s.base, "date_format": "1", "range_from": cur.isoformat(),
                                        "range_to": end.isoformat(), "cont_flag": s.cont})
            cur = end + dt.timedelta(days=1)
        return out

    async def history(self, params: dict) -> dict:
        STATS.roll()
        STATS.requests += 1
        res = str(params.get("resolution", "5")).upper()
        base = BASE_OF.get(res)
        if base is None:                                    # W / M: not worth storing
            STATS.fetched += 1
            return await self.fetch("/history", params)
        sym = str(params["symbol"])
        cont = str(params.get("cont_flag", "1"))
        fmt = str(params.get("date_format", "1"))
        a, b = _to_date(params["range_from"], fmt), _to_date(params["range_to"], fmt)
        key = (sym, base, cont)
        s = self.series.get(key)
        if s is None:
            s = self.series[key] = Series(sym, base, cont)
        now = self.clock()
        s.last_req = now
        today = dt.datetime.fromtimestamp(now, IST).date()
        async with s.lock:
            try:
                if s.cov_from is None or a < s.cov_from:       # history not downloaded yet (or older history wanted)
                    stop = (s.cov_from - dt.timedelta(days=1)) if s.cov_from else max(b, today)
                    rows = await self._download(s, a, stop)
                    s.merge(rows)
                    s.cov_from = a
                    if stop >= today:
                        s.last_fetch = now
                if b >= today and s.needs_update(now, self._factor()):
                    since = dt.datetime.fromtimestamp(s.rows[-1][0], IST).date() if s.rows else a
                    s.merge(await self._download(s, since, today))
                    s.last_fetch = now
            except Exception:
                if not s.rows:
                    raise
                STATS.stale_served += 1                     # FYERS refused: serve what is stored
        rows = s.slice(a, b)
        if res != base and base != "D":
            rows = resample(rows, int(res), _anchor(sym))
        return {"s": "ok", "candles": [list(r) for r in rows]}

    async def quote(self, params: dict) -> dict:
        STATS.roll()
        STATS.requests += 1
        syms = [x.strip() for x in str(params.get("symbols", "")).split(",") if x.strip()]
        now = self.clock()
        age = QUOTE_AGE * self._factor()
        miss = [x for x in syms if x not in self.quotes or now - self.quotes[x][0] >= age]
        if miss:
            STATS.fetched += 1
            try:
                p = await self.fetch("/quotes", {**params, "symbols": ",".join(miss)})
            except Exception:
                if any(x not in self.quotes for x in syms):
                    raise
                STATS.stale_served += 1
                p = {"d": []}
            for d in p.get("d") or []:
                n = d.get("n") or (d.get("v") or {}).get("symbol")
                if n:
                    self.quotes[n] = (now, d)
            for x in miss:                                  # FYERS may echo a different spelling: keep the order we were asked
                if x not in self.quotes:
                    hit = next((d for d in p.get("d") or [] if (d.get("n") or "").upper() == x.upper()), None)
                    if hit:
                        self.quotes[x] = (now, hit)
        return {"s": "ok", "code": 200, "d": [self.quotes[x][1] for x in syms if x in self.quotes]}

    async def chain(self, params: dict) -> dict:
        STATS.roll()
        STATS.requests += 1
        key = tuple(sorted((k, str(v)) for k, v in params.items()))
        now = self.clock()
        hit = self.chains.get(key)
        if hit and now - hit[0] < CHAIN_AGE * self._factor():
            return hit[1]
        STATS.fetched += 1
        try:
            p = await self.fetch("/options-chain-v3", params)
        except Exception:
            if hit:
                STATS.stale_served += 1
                return hit[1]
            raise
        self.chains[key] = (now, p)
        if len(self.chains) > 200:
            for k in sorted(self.chains, key=lambda k: self.chains[k][0])[:50]:
                self.chains.pop(k, None)
        return p

    def wanted(self, now: float, within: float = 1800.0) -> list[str]:
        """Intraday symbols asked for recently, most recent first (the live feed subscribes to these)."""
        last: dict[str, float] = {}
        for (sym, base, _), s in self.series.items():
            if base in ("1", "5") and now - s.last_req <= within:
                last[sym] = max(last.get(sym, 0.0), s.last_req)
        return sorted(last, key=lambda k: -last[k])

    def apply_tick(self, symbol: str, price: float, t: float, dvol: float = 0.0) -> int:
        """A live price: extend / update the newest 1- and 5-minute candles of `symbol` (REST data replaces these
        candles at the next download, so the download stays the reference). Returns how many series changed."""
        n = 0
        for (sym, base, _), s in self.series.items():
            if sym != symbol or base not in ("1", "5") or not s.rows:
                continue
            step = s.step
            start = int(t - (t % step))
            last = s.rows[-1]
            if start == int(last[0]):
                last[2] = max(last[2], price)
                last[3] = min(last[3], price)
                last[4] = price
                last[5] = (last[5] or 0) + dvol
            elif start > int(last[0]):
                if not market_open(sym, t):
                    continue
                s.rows.append([start, price, price, price, price, dvol])
            else:
                continue
            n += 1
        return n

    def status(self) -> dict:
        STATS.roll()
        return {"symbols": len({k[0] for k in self.series}), "series": len(self.series),
                "candles": sum(len(s.rows) for s in self.series.values()), "requests_today": STATS.requests,
                "sent_to_fyers_today": STATS.fetched, "served_from_store_today": max(0, STATS.requests - STATS.fetched),
                "stale_served_today": STATS.stale_served, "update_every_s": round(MIN_REFRESH * self._factor())}

