"""Live analysis for the Signal Lab screen: one call returns chart data, overlays, intelligence and signals."""
from __future__ import annotations

import asyncio
import json
import time
from dataclasses import asdict

from .candle import TF_SECONDS
from . import data as D
from . import ind as I
from . import ict as ICT
from . import msb as MSB
from . import pa as PA
from . import options as O
from . import store
from . import strategies as ST
from . import protect as P
from . import active as AC
from .engine import Engine, MTF

CRYPTO_OPT = ("BTC", "ETH")
_chain_cache: dict[str, tuple[float, dict]] = {}


def underlying_of(symbol: str) -> tuple[str | None, str]:
    """Option-chain underlying for a symbol, and its kind (india | crypto | none)."""
    s = symbol.upper()
    m = D.market_of(s)
    if m in ("NSE", "FNO"):
        body = s.split(":", 1)[1]
        for k, v in (("NIFTYBANK", "BANKNIFTY"), ("BANKNIFTY", "BANKNIFTY"), ("FINNIFTY", "FINNIFTY"), ("MIDCPNIFTY", "MIDCPNIFTY"),
                     ("NIFTY", "NIFTY"), ("SENSEX", "SENSEX"), ("BANKEX", "BANKEX")):
            if body.startswith(k):
                return v, "india"
        return None, "none"
    if m in ("SHARK", "DELTAF", "BINANCE", "DELTA"):
        base = s.split(":", 1)[1].split("-")[0].replace("USDT", "").replace("USD", "")
        if base.startswith("C") and "-" in s:
            base = s.split(":", 1)[1].split("-")[1]
        return (base, "crypto") if base in CRYPTO_OPT else (None, "none")
    return None, "none"


async def derivatives(symbol: str, save: bool = True) -> dict:
    und, kind = underlying_of(symbol)
    out: dict = {"symbol": symbol, "underlying": und, "kind": kind}
    if kind == "none":
        out["note"] = "No listed options for this instrument in the connected sources."
    else:
        hit = _chain_cache.get(und)
        if hit and time.time() - hit[0] < 60:
            ch = hit[1]
        else:
            try:
                ch = await (O.india_chain(und) if kind == "india" else O.crypto_chain(und))
            except Exception as exc:                      # noqa: BLE001
                ch = {"error": f"DATA UNAVAILABLE: {str(getattr(exc, 'detail', exc))[:160]}"}
            if not ch.get("error"):
                _chain_cache[und] = (time.time(), ch)
                if save:
                    O.save_snapshot(ch)
        out["chain"] = ch
        if not ch.get("error"):
            ch["trends"] = O.history_trends(und)
    m = D.market_of(symbol)
    if m in ("SHARK", "DELTAF", "BINANCE"):
        pair = symbol.split(":", 1)[1]
        out["perp"] = await O.crypto_derivs(pair)
    return out


def _quality_recent(bars, step) -> int:
    tail = bars[-21:]
    return sum(1 for a, b in zip(tail, tail[1:]) if b.time - a.time > step and (b.time - a.time) < 3 * 3600)


def _overlays(E: Engine, n: int) -> dict:
    F = E.F
    lo = max(0, len(F.bars) - n)
    T = F.t[lo:]
    line = lambda xs: [{"time": t, "value": round(v, 6)} for t, v in zip(T, xs[lo:]) if v is not None]
    t_last = F.t[-1]
    obs = [{"direction": o.direction, "top": o.top, "bottom": o.bottom, "time": o.time, "state": o.state, "break_type": o.break_type,
            "volume_confirmed": o.volume_confirmed} for o in F.obs_at(t_last) if o.time >= F.t[lo]][-12:]
    fvgs = [{k: g[k] for k in ("direction", "top", "bottom", "ce", "time", "quality")} for g in F.open_fvgs_at(t_last) if g["time"] >= F.t[lo]][-12:]
    marks = []
    for s in F.ext.structure:
        if s.time >= F.t[lo]:
            marks.append({"time": s.time, "kind": s.type, "direction": s.direction, "level": s.level})
    for s in F.ext.sweeps + F.intl.sweeps:
        if s.time >= F.t[lo]:
            marks.append({"time": s.time, "kind": "sweep", "direction": "bullish" if s.side == "sell" else "bearish", "level": s.level})
    above, below = F.liquidity_at(t_last, F.c[-1])
    return {"ema20": line(F.ema[20]), "ema50": line(F.ema[50]), "ema200": line(F.ema[200]), "vwap": line(F.vwap) if F.step < 86400 else [],
            "bb_up": line(F.bb_up), "bb_lo": line(F.bb_lo), "supertrend": line(F.st_line), "order_blocks": obs, "fvgs": fvgs,
            "markers": sorted(marks, key=lambda m: m["time"])[-80:], "liquidity_above": above[:6], "liquidity_below": below[:6]}


def _indicators(E: Engine) -> dict:
    F, i = E.F, len(E.F.bars) - 1
    bars = F.bars
    L = lambda xs: xs[i] if xs and xs[i] is not None else None
    india = E.market in ("NSE", "FNO", "MCX")
    ppy = (252 if india or E.market == "YF" else 365) * (1 if F.step >= 86400 else (375 * 60 if india else 86400) / F.step)
    hv = I.hist_vol(F.c, 20, ppy)
    vp = I.volume_profile(bars[-200:]) if F.has_volume else None
    hs, ls = F.swings_at(F.t[i], "high"), F.swings_at(F.t[i], "low")
    fib = None
    if hs and ls:
        up = ls[-1].time < hs[-1].time
        fib = {"from": ls[-1].price if up else hs[-1].price, "to": hs[-1].price if up else ls[-1].price, "direction": "up" if up else "down",
               "levels": I.fib_levels(ls[-1].price, hs[-1].price, up)}
    div = I.divergences(bars, F.rsi, "RSI")[-4:] + I.divergences(bars, F.macd_hist, "MACD")[-4:]
    obv_slope = (F.obv[i] - F.obv[i - 10]) if i >= 10 else None
    return {"close": F.c[i], "ema": {n: L(F.ema[n]) for n in F.ema}, "sma": {n: L(F.sma[n]) for n in F.sma}, "rsi": L(F.rsi),
            "stoch_rsi": {"k": L(F.srsi_k), "d": L(F.srsi_d)}, "macd": {"macd": L(F.macd), "signal": L(F.macd_sig), "hist": L(F.macd_hist)},
            "adx": {"adx": L(F.adx), "plus_di": L(F.pdi), "minus_di": L(F.mdi)},
            "bollinger": {"mid": L(F.bb_mid), "up": L(F.bb_up), "lo": L(F.bb_lo), "bandwidth_pct": L(F.bb_bw)},
            "keltner": {"mid": L(F.kc_mid), "up": L(F.kc_up), "lo": L(F.kc_lo)},
            "squeeze": bool(F.bb_up[i] and F.kc_up[i] and F.bb_up[i] < F.kc_up[i] and F.bb_lo[i] > F.kc_lo[i]),
            "supertrend": {"line": L(F.st_line), "dir": L(F.st_dir)}, "atr": L(F.atr), "atr_pct": (L(F.atr) / F.c[i] * 100) if L(F.atr) else None,
            "vwap": L(F.vwap) if F.step < 86400 else None, "mfi": L(F.mfi) if F.has_volume else None, "obv_slope_10": obv_slope if F.has_volume else None,
            "rvol": L(F.rvol) if F.has_volume else None, "roc": L(F.roc), "hist_vol_pct": L(hv), "parkinson_vol_pct": I.last(I.parkinson_vol(bars)),
            "volume_profile": vp, "fib": fib, "divergences": div, "has_volume": F.has_volume}


async def analyze(symbol: str, tf: str, bars: int = 600, fresh: bool = False, live: bool = False) -> dict:
    t0 = time.time()
    itf, htf = MTF[tf]
    sess, anchor, market = D.session_key(symbol), D.anchor_minutes(symbol), D.market_of(symbol)
    main, q = await D.candles(symbol, tf, bars, fresh, forming=live)  # DataUnavailable propagates -> DATA UNAVAILABLE on screen
    q["recent_gaps"] = _quality_recent(main, TF_SECONDS[tf])

    async def opt(sym, t, n):
        if not t:
            return None, None
        try:
            return await D.candles(sym, t, n)
        except Exception as exc:                          # noqa: BLE001
            return None, {"error": str(exc)[:160]}
    (ib, iq), (hb, hq), (db, dq) = await asyncio.gather(opt(symbol, itf, 400), opt(symbol, htf, 400),
                                                          opt(symbol, "1d", 120) if tf != "1d" else asyncio.sleep(0, (main, q)))
    E = Engine(main, tf, market, sess, anchor, ib, hb)
    der = await derivatives(symbol) if TF_SECONDS[tf] < 86400 or underlying_of(symbol)[1] != "none" else None
    ch = (der or {}).get("chain") if der else None
    opt_ctx = None
    if ch and not ch.get("error"):
        opt_ctx = {"oi_flow": ch.get("oi_flow"), "trends": ch.get("trends")}
    settings = store.get_setting("strategies") or {}
    i = len(main) - 1
    res = E.signals_at(i, opt_ctx, settings, q)
    val = store.get_setting(f"validation:{symbol}:{tf}") or {}
    prot = P.settings()
    for s in res["setups"]:
        s["validation"] = (val.get("status") or {}).get(s["strategy"], {"status": "not backtested"})
        s["size"] = P.size(symbol, market, s["entry"], s["stop"], prot)
        s["signal"] = s["score"] >= prot["min_score"]
        s["provisional"] = bool(q.get("forming"))
    # Setups from the last CLOSED candle: with a forming candle that is the one before it. Only these can be locked.
    if q.get("forming") and i >= 1:
        closed = E.signals_at(i - 1, opt_ctx, settings, q)["setups"]
        for s in closed:
            s["validation"] = (val.get("status") or {}).get(s["strategy"], {"status": "not backtested"})
            s["size"] = P.size(symbol, market, s["entry"], s["stop"], prot)
    else:
        closed = res["setups"]
    _journal(symbol, tf, closed, prot["min_score"])     # journal / locks only from closed candles (a live candle can still change)
    try:
        AC.update(symbol, tf, main, sess, market, TF_SECONDS[tf])
        AC.lock(symbol, tf, closed, prot["min_score"])
        AC.update(symbol, tf, main, sess, market, TF_SECONDS[tf])   # a just-locked setup may already be tapped by the forming candle
        shown, recent_locked = AC.merge(symbol, tf, res["setups"], main[-1].close)
    except Exception:                                 # noqa: BLE001 - locking must never break analysis
        shown, recent_locked = res["setups"], []
    try:
        marks = AC.history(symbol, tf, main[-400].time if len(main) >= 400 else main[0].time)
    except Exception:                                 # noqa: BLE001
        marks = []
    for s in shown:
        if s.get("locked"):
            s["signal"] = True
            s["size"] = P.size(symbol, market, s["entry"], s["stop"], prot)
    ictr = ICT.analyze(main, market, db or None, main[-1].time)
    ext, intl, obs = ictr.pop("_reports")
    traps = [asdict(t) for t in ext.traps]
    par = PA.analyze(main, E.F.disp, traps)
    try:                                              # MSB / order blocks (msb.py): structure + zone location for the agent
        _m = MSB.analyze(main)
        msbr = {k: _m[k] for k in ("structure", "last_msb", "nearest_demand", "nearest_supply", "in_zone", "retest_now", "vote", "summary", "active")}
    except Exception as exc:                          # noqa: BLE001 - never break analysis
        msbr = {"error": str(exc)[:160]}
    ctx = res["ctx"]
    ctx.pop("options", None)
    reg = ctx.pop("regime_full")
    mtf = {"execution": tf, "intermediate": {"tf": itf, "bias": ctx["itf_bias"], "available": ctx["itf_ok"], "error": (iq or {}).get("error")},
           "higher": {"tf": htf, "bias": ctx["htf_bias"], "available": ctx["htf_ok"], "error": (hq or {}).get("error")},
           "execution_bias": E.F.bias_at(i)}
    liq = {}
    if ch and not ch.get("error"):
        liq["oi_support"], liq["oi_resistance"], liq["max_pain"] = ch.get("oi_support"), ch.get("oi_resistance"), ch.get("max_pain")
    if (der or {}).get("perp") and not der["perp"].get("error"):
        hs, ls = E.F.swings_at(E.F.t[i], "high"), E.F.swings_at(E.F.t[i], "low")
        der["liquidations"] = O.liquidation_estimates(main[-1].close, ls[-1].price if ls else None, hs[-1].price if hs else None)
    candles_out = [{"time": b.time, "open": b.open, "high": b.high, "low": b.low, "close": b.close, "volume": b.volume} for b in main[-400:]]
    if not q.get("forming"):
        _alerts(symbol, tf, E, res, prot)
    return {"symbol": symbol, "tf": tf, "market": market, "quality": q, "candles": candles_out, "overlays": _overlays(E, 400),
            "indicators": _indicators(E), "regime": reg, "score": res["score"], "setups": shown[:8], "locked_history": recent_locked, "signal_marks": marks,
            "rejected": res["rejected"][:20], "context": ctx, "mtf": mtf, "ict": ictr, "msb": msbr, "price_action": par, "derivatives": der,
            "levels": liq, "validation": val.get("summary"), "elapsed_ms": int((time.time() - t0) * 1000),
            "disclaimer": "Analysis and paper trading only. Scores rank setups; they are not probabilities of profit."}


def _journal(symbol: str, tf: str, setups: list[dict], min_score: float) -> None:
    for s in setups:
        if s["score"] < min_score:
            continue
        try:
            store.execute("INSERT OR IGNORE INTO signals(created,symbol,tf,strategy,direction,score,bull,bear,neutral,entry,stop,t1,t2,t3,rr,status,bar_time,payload)"
                          " VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                          (store.now(), symbol, tf, s["strategy"], s["direction"], s["score"], None, None, None, s["entry"], s["stop"],
                           s["targets"][0], s["targets"][1], s["targets"][2], s["rr"], "open", s["time"],
                           json.dumps({k: s[k] for k in ("reasons_for", "reasons_against", "grade", "atr", "regime", "expected_hold")})))
        except Exception:                                 # noqa: BLE001 - the journal must never break analysis
            pass


def _alerts(symbol: str, tf: str, E: Engine, res: dict, prot: dict) -> None:
    F = E.F
    i = len(F.bars) - 1
    t = F.t[i]
    for s in res["setups"]:
        if s["score"] >= prot["min_score"]:
            store.add_alert(f"sig:{symbol}:{tf}:{s['strategy']}:{s['direction']}:{t}", t, symbol, tf, "signal",
                            f"{s['direction']} {s['name']} score {s['score']:.0f} ({s['grade']}) entry {s['entry']:,.2f} stop {s['stop']:,.2f}")
    for sw in F.sweeps_between(F.t[max(0, i - 1)], t):
        store.add_alert(f"sweep:{symbol}:{tf}:{sw.time}:{sw.level}", sw.time, symbol, tf, "sweep",
                        f"{'Buy' if sw.side == 'buy' else 'Sell'}-side liquidity swept at {sw.level:,.2f}")
    for m in F.mss_between(F.t[max(0, i - 1)], t):
        store.add_alert(f"mss:{symbol}:{tf}:{m['time']}", m["time"], symbol, tf, "structure", f"{m['direction'].title()} market-structure shift at {m['level']:,.2f}")


async def mtf_matrix(symbol: str) -> dict:
    """Bias, trend, RSI and regime on every timeframe (fetched sequentially to respect rate limits)."""
    from . import regime as R
    sess, anchor, market = D.session_key(symbol), D.anchor_minutes(symbol), D.market_of(symbol)
    rows = []
    for tf in ("1w", "1d", "4h", "1h", "30m", "15m", "5m", "3m", "1m"):
        try:
            b, q = await D.candles(symbol, tf, 300)
            if len(b) < 60:
                rows.append({"tf": tf, "error": f"only {len(b)} candles"})
                continue
            E = Engine(b, tf, market, sess, anchor)
            F, i = E.F, len(b) - 1
            reg = R.classify_at(F, i)
            rows.append({"tf": tf, "bias": F.bias_at(i), "structure": F.trend_at(F.t[i]), "rsi": F.rsi[i], "adx": F.adx[i],
                         "regime": reg["label"], "close": F.c[i], "ema20": F.ema[20][i], "ema50": F.ema[50][i], "as_of": q["as_of"], "source": q["source"]})
        except Exception as exc:                          # noqa: BLE001
            rows.append({"tf": tf, "error": f"DATA UNAVAILABLE: {str(exc)[:120]}"})
    vals = [r["bias"] for r in rows if "bias" in r]
    groups = {"higher (1w/1d/4h)": ["1w", "1d", "4h"], "intermediate (1h/30m/15m)": ["1h", "30m", "15m"], "execution (5m/3m/1m)": ["5m", "3m", "1m"]}
    g_out = {}
    for name, tfs in groups.items():
        v = [r["bias"] for r in rows if r["tf"] in tfs and "bias" in r]
        g_out[name] = (1 if sum(v) >= 2 else -1 if sum(v) <= -2 else 0) if v else None
    agree = [x for x in g_out.values() if x is not None]
    return {"symbol": symbol, "rows": rows, "groups": g_out,
            "alignment": "aligned bullish" if agree and all(x == 1 for x in agree) else "aligned bearish" if agree and all(x == -1 for x in agree) else "mixed",
            "net": sum(vals)}

backend/lab/auction.py:
"""AuctionFlow Market Structure Engine (Auction Market Theory). Analysis only: nothing here places or sizes a trade.

Profiles ("profile session: both")
  * SESSION profiles: one per trading day (IST 09:15-15:30 for NSE/BSE/MCX, UTC day for crypto/US), each with a
    Volume Profile (each candle's volume spread evenly over the price bins it traded) and a TPO profile (30-minute
    periods; a bin earns one TPO per period that traded it). POC = busiest bin; Value Area = 70% around the POC,
    grown two bins at a time toward the busier side (CBOT method). The current day's POC/VAH/VAL are also given
    candle by candle ("developing").
  * COMPOSITE profiles: the whole window and every balance area, Volume and TPO.
  Indices have no traded volume: their Volume Profile uses the front-month future's volume, candle by candle.

Balance (auto)
  Candle by candle, a balance is a block of candles rotating around its own value: it needs >= MIN_BAL candles
  (about an hour) and >= 2 crossings of its POC. When >= ACCEPT closes in a row land outside the block's value area
  ("acceptance"), the balance ends and an IMBALANCE leg starts (bullish up, bearish down) until a new block
  qualifies. All thresholds scale with ATR and the timeframe, so nothing needs a fixed lookback.
  Multi-day balance: consecutive sessions whose value areas overlap >= 50% (of the narrower one) are one balance.

Failed auctions
  A close beyond a balance's value area (or beyond the prior session's high/low) that returns inside the value
  within FAIL_BARS candles without acceptance: "look above and fail" (bearish) / "look below and fail" (bullish).
  TPO poor high/low: >= 2 TPOs at the extreme (no excess: unfinished auction, often revisited); excess: a tail of
  single TPOs at the extreme (the auction ended there). Single prints inside the day = initiative imbalance.

HVN / LVN: smoothed composite volume profile; peaks >= 1.25x average with clear prominence = HVN, troughs <= 0.6x
average between two HVNs = LVN (price tends to move fast through LVNs and stall at HVNs).

Next balance projection (direction of the latest imbalance, or both sides while in balance): the nearest of the
next historical balance area / HVN beyond price, else a measured move (edge +/- the height of the balance left).

Confluence: every VP and TPO level (POC/VAH/VAL of the current and previous sessions, the composite and the
balances, naked POCs, HVN/LVN) is clustered within 0.35 ATR; a zone where Volume AND TPO levels agree scores higher.
"""
from __future__ import annotations

import asyncio
import datetime as dt
import math
import time

from .candle import Candle, TF_SECONDS

IST = dt.timezone(dt.timedelta(hours=5, minutes=30))
VA_PCT = 0.70
TPO_SEC = 1800
MIN_BAL_SEC = 3600            # a balance needs about an hour of candles
ACCEPT = 3                    # closes in a row outside value = acceptance
FAIL_BARS = 4                 # back inside value within this many candles = failed auction
OVERLAP = 0.5                 # multi-day balance: value areas overlapping >= 50%
INDEX_FUT = {"NSE:NIFTY50-INDEX": "NSE:NIFTY-FUT", "NSE:NIFTYBANK-INDEX": "NSE:BANKNIFTY-FUT", "NSE:FINNIFTY-INDEX": "NSE:FINNIFTY-FUT",
             "NSE:MIDCPNIFTY-INDEX": "NSE:MIDCPNIFTY-FUT", "BSE:SENSEX-INDEX": "BSE:SENSEX-FUT", "BSE:BANKEX-INDEX": "BSE:BANKEX-FUT"}
_cache: dict = {}


# ---------------------------------------------------------------- profile maths
def nice_bin(raw: float) -> float:
    if raw <= 0:
        return 0.01
    e = 10 ** math.floor(math.log10(raw))
    for m in (1, 2, 2.5, 5, 10):
        if raw <= m * e:
            return m * e
    return 10 * e


class Grid:
    """Price bins of one size for every profile, so levels line up across sessions."""

    def __init__(self, lo: float, step: float):
        self.step = step
        self.base = math.floor(lo / step) * step

    def idx(self, p: float) -> int:
        return int(math.floor((p - self.base) / self.step + 1e-9))

    def price(self, i: int) -> float:                  # bin centre
        return self.base + (i + 0.5) * self.step


def add_bar(vp: dict, tpo_seen: dict, g: Grid, b: Candle, period: int, vol: float) -> None:
    lo, hi = g.idx(b.low), g.idx(b.high)
    n = hi - lo + 1
    for i in range(lo, hi + 1):
        vp[i] = vp.get(i, 0.0) + vol / n
        tpo_seen.setdefault(i, set()).add(period)


def poc_va(prof: dict) -> dict | None:
    """POC and 70% value area of {bin: amount}. Ties for POC go to the bin nearest the profile's middle."""
    if not prof:
        return None
    keys = sorted(prof)
    lo_k, hi_k = keys[0], keys[-1]
    full = [prof.get(i, 0.0) for i in range(lo_k, hi_k + 1)]
    tot = sum(full)
    if tot <= 0:
        return None
    mx = max(full)
    mid = (len(full) - 1) / 2
    p = min((i for i, v in enumerate(full) if v == mx), key=lambda i: abs(i - mid))
    a = b = p
    acc = full[p]
    while acc < VA_PCT * tot and (a > 0 or b < len(full) - 1):
        up = sum(full[b + 1:b + 3]) if b < len(full) - 1 else -1
        dn = sum(full[max(0, a - 2):a]) if a > 0 else -1
        if up >= dn:
            nb = min(len(full) - 1, b + 2)
            acc += sum(full[b + 1:nb + 1])
            b = nb
        else:
            na = max(0, a - 2)
            acc += sum(full[na:a])
            a = na
    return {"poc": lo_k + p, "val": lo_k + a, "vah": lo_k + b, "lo": lo_k, "hi": hi_k, "total": tot}


def levels(g: Grid, pv: dict | None) -> dict | None:
    if not pv:
        return None
    s = g.step
    return {"poc": round(g.price(pv["poc"]), 6), "vah": round(g.base + (pv["vah"] + 1) * s, 6), "val": round(g.base + pv["val"] * s, 6)}


def profile_of(bars: list[Candle], vols: list[float], g: Grid, t0: int) -> tuple[dict, dict]:
    vp, seen = {}, {}
    for b, v in zip(bars, vols):
        add_bar(vp, seen, g, b, (b.time - t0) // TPO_SEC, v)
    return vp, {i: len(s) for i, s in seen.items()}


def _atr(bars: list[Candle], n: int = 14) -> float:
    if len(bars) < 2:
        return (bars[0].high - bars[0].low) if bars else 0.0
    trs = [max(b.high - b.low, abs(b.high - a.close), abs(b.low - a.close)) for a, b in zip(bars, bars[1:])]
    k = trs[-max(n * 20, n):]
    return sum(k) / len(k) if k else 0.0


# ---------------------------------------------------------------- sessions
def session_id(symbol: str):
    india = symbol.split(":", 1)[0].upper() in ("NSE", "BSE", "MCX") or symbol.upper().endswith(("-EQ", "-INDEX", "-FUT"))
    off = 19800 if india else 0
    return (lambda t: (t + off) // 86400), off


def tpo_detail(tpo: dict, g: Grid, first_hour: tuple[float, float] | None) -> dict:
    if not tpo:
        return {}
    keys = sorted(tpo)
    top, bot = keys[-1], keys[0]
    singles, run = [], []
    for i in range(bot, top + 1):                     # inside single prints (initiative)
        if tpo.get(i, 0) == 1:
            run.append(i)
        else:
            if len(run) >= 2 and run[0] != bot and run[-1] != top:
                singles.append([round(g.base + run[0] * g.step, 6), round(g.base + (run[-1] + 1) * g.step, 6)])
            run = []

    def tail(rng):
        n = 0
        for i in rng:
            if tpo.get(i, 0) == 1:
                n += 1
            else:
                break
        return n
    th, tl = tail(range(top, bot - 1, -1)), tail(range(bot, top + 1))
    out = {"poor_high": tpo.get(top, 0) >= 2 and tpo.get(top - 1, 0) >= 2, "poor_low": tpo.get(bot, 0) >= 2 and tpo.get(bot + 1, 0) >= 2,
           "excess_high": th >= 2, "excess_low": tl >= 2, "single_prints": singles[:6]}
    if first_hour:
        out["ib"] = [round(first_hour[0], 6), round(first_hour[1], 6)]
    return out


# ---------------------------------------------------------------- balance / imbalance / failed auctions (candle by candle)
def segment(bars: list[Candle], g: Grid, step_sec: int, at: float) -> dict:
    """Walk the candles once: balance blocks, the imbalance legs between them and failed breakouts of a balance."""
    min_bal = max(6, MIN_BAL_SEC // step_sec)
    balances, legs, failed = [], [], []
    st = {"s": 0, "pr": {}}

    def add(k, sign=1):
        for i in range(g.idx(bars[k].low), g.idx(bars[k].high) + 1):
            st["pr"][i] = st["pr"].get(i, 0) + sign

    def reset(s0, k_end):
        st["s"], st["pr"] = s0, {}
        for k in range(s0, k_end + 1):
            add(k)

    def rotations(a, b, poc_p):
        n, side = 0, 0
        for k in range(a, b + 1):
            sd = 1 if bars[k].close > poc_p else -1 if bars[k].close < poc_p else 0
            if sd and side and sd != side:
                n += 1
            side = sd or side
        return n

    def qualifies(a, b):
        """Levels of the block a..b (profile in st['pr']) if it is a balance, else None."""
        if b - a + 1 < min_bal:
            return None
        pv = poc_va({i: v for i, v in st["pr"].items() if v > 0})
        if not pv or rotations(a, b, g.price(pv["poc"])) < 2:
            return None
        return pv

    def block_pv(a, b):
        pr = {}
        for k in range(a, b + 1):
            for i in range(g.idx(bars[k].low), g.idx(bars[k].high) + 1):
                pr[i] = pr.get(i, 0) + 1
        return poc_va(pr)

    def close_block(a, b, pv, status):
        balances.append({"start": bars[a].time, "end": bars[b].time, "i0": a, "i1": b, "bars": b - a + 1, "status": status, "kind": "intraday",
                         "high": max(x.high for x in bars[a:b + 1]), "low": min(x.low for x in bars[a:b + 1]), **levels(g, pv)})

    up = dn = 0
    probe = None                                       # (side, candle index, the block extreme it went beyond)
    brk_watch = None                                   # a fresh breakout: (old start, balance, leg, side, candle index, old VAL, old VAH, POC)
    if bars:
        add(0)
    for k in range(1, len(bars)):
        s = st["s"]
        c = bars[k].close
        # a breakout that comes straight back inside the old value: failed auction, the balance continues
        if brk_watch and k - brk_watch[4] <= ACCEPT + FAIL_BARS:
            os_, bal, leg, side, kb, oval, ovah, opoc = brk_watch
            if oval <= c <= ovah:
                ext = max(x.high for x in bars[kb:k + 1]) if side == "high" else min(x.low for x in bars[kb:k + 1])
                failed.append({"t": bars[k].time, "t_probe": bars[kb].time, "side": side, "price": round(ext, 6),
                               "ref": "balance breakout", "ref_price": round(ovah if side == "high" else oval, 6),
                               "target": round(opoc, 6), "target2": round(oval if side == "high" else ovah, 6)})
                balances.remove(bal)
                legs.remove(leg)
                reset(os_, k)
                brk_watch, up, dn, probe = None, 0, 0, None
                continue
        elif brk_watch:
            brk_watch = None
        pv = qualifies(s, k - 1)
        if pv:
            vah, val = g.base + (pv["vah"] + 1) * g.step, g.base + pv["val"] * g.step
            hi_b = max(x.high for x in bars[s:k])
            lo_b = min(x.low for x in bars[s:k])
            if probe and k - probe[1] > FAIL_BARS:
                probe = None
            if probe is None and bars[k].high > hi_b:
                probe = ("high", k, hi_b)
            elif probe is None and bars[k].low < lo_b:
                probe = ("low", k, lo_b)
            if c > vah:
                up, dn = up + 1, 0
            elif c < val:
                dn, up = dn + 1, 0
            else:
                if probe and probe[1] < k:             # went beyond the balance range and closed back in value
                    side, kp, lvl = probe
                    ext = max(x.high for x in bars[kp:k]) if side == "high" else min(x.low for x in bars[kp:k])
                    failed.append({"t": bars[k].time, "t_probe": bars[kp].time, "side": side, "price": round(ext, 6),
                                   "ref": f"balance {side}", "ref_price": round(lvl, 6),
                                   "target": round(g.price(pv["poc"]), 6), "target2": round(val if side == "high" else vah, 6)})
                    probe = None
                up = dn = 0
            run = up or dn
            if run >= ACCEPT:
                r0 = k - ACCEPT + 1
                ref_hi = max(x.high for x in bars[s:r0]) if r0 > s else hi_b
                ref_lo = min(x.low for x in bars[s:r0]) if r0 > s else lo_b
                beyond = any(x.close > ref_hi for x in bars[r0:k + 1]) if up else any(x.close < ref_lo for x in bars[r0:k + 1])
                if beyond:                             # acceptance: closes outside value AND beyond the balance range
                    old = block_pv(s, r0 - 1)
                    close_block(s, r0 - 1, old, "historical")
                    leg = {"i0": r0, "dir": "bull" if up else "bear"}
                    legs.append(leg)
                    lv = levels(g, old)
                    brk_watch = (s, balances[-1], leg, "high" if up else "low", r0, lv["val"], lv["vah"], lv["poc"])
                    reset(r0, k)
                    up = dn = 0
                    probe = None
                    continue
            add(k)
        else:
            add(k)
            # not a balance yet: a run-away stretch is part of the move, so the candidate block slides forward
            if k - s + 1 > min_bal:
                hi, lo = max(x.high for x in bars[s:k + 1]), min(x.low for x in bars[s:k + 1])
                if (hi - lo) > 3.5 * at and rotations(s, k, (hi + lo) / 2) < 2:
                    reset(k - min_bal + 1, k)
    s = st["s"]
    pv = qualifies(s, len(bars) - 1)
    if pv:
        close_block(s, len(bars) - 1, pv, "developing")
    for lg in legs:                                    # a leg runs from the breakout until the next balance begins
        nxt = next((b for b in balances if b["i0"] >= lg["i0"]), None)
        if nxt:
            i1 = min(nxt["i1"], max(nxt["i0"] - 1, lg["i0"] + ACCEPT - 1))
        else:
            i1 = len(bars) - 1
        seg = bars[lg["i0"]:i1 + 1] or [bars[lg["i0"]]]
        a, b = seg[0].open, seg[-1].close
        lg.update(start=seg[0].time, end=seg[-1].time, i1=i1, frm=round(a, 6), to=round(b, 6), high=max(x.high for x in seg),
                  low=min(x.low for x in seg), size_atr=round(abs(b - a) / at, 2) if at else None, status="historical" if nxt else "developing")
    return {"balances": balances, "imbalances": legs, "failed": failed, "min_bal": min_bal}


def multiday(sessions: list[dict]) -> list[dict]:
    """Consecutive sessions whose value areas overlap >= 50% form one multi-day balance."""
    out, cur = [], []
    for s in sessions:
        va = s.get("tpo_lv") or s.get("vp_lv")
        if not va:
            continue
        if cur:
            cl, ch = min(x["va"][0] for x in cur), max(x["va"][1] for x in cur)
            ov = min(ch, va["vah"]) - max(cl, va["val"])
            narrow = min(ch - cl, va["vah"] - va["val"]) or 1e-9
            if ov / narrow >= OVERLAP:
                cur.append({"s": s, "va": (va["val"], va["vah"])})
                continue
            out.append(cur)
        cur = [{"s": s, "va": (va["val"], va["vah"])}]
    if cur:
        out.append(cur)
    return [c for c in out if len(c) >= 2]


# ---------------------------------------------------------------- HVN / LVN
def nodes(prof: dict, g: Grid) -> dict:
    if not prof:
        return {"hvn": [], "lvn": []}
    keys = range(min(prof), max(prof) + 1)
    raw = [prof.get(i, 0.0) for i in keys]
    k = [1, 2, 3, 2, 1]
    sm = []
    for i in range(len(raw)):
        acc = w = 0.0
        for j, kk in enumerate(k):
            x = i + j - 2
            if 0 <= x < len(raw):
                acc += raw[x] * kk
                w += kk
        sm.append(acc / w)
    avg = sum(sm) / len(sm) if sm else 0
    peaks = [i for i in range(1, len(sm) - 1) if sm[i] >= sm[i - 1] and sm[i] > sm[i + 1] and sm[i] >= 1.25 * avg]
    sep = max(3, len(sm) // 25)
    hv: list[int] = []
    for i in sorted(peaks, key=lambda i: -sm[i]):
        if all(abs(i - j) >= sep for j in hv):
            hv.append(i)
    hv.sort()
    lv = []
    for a, b in zip(hv, hv[1:]):
        m = min(range(a, b + 1), key=lambda i: sm[i])
        if sm[m] <= 0.6 * avg and sm[m] <= 0.5 * min(sm[a], sm[b]):
            lv.append(m)
    base = min(prof)
    P = lambda i: round(g.price(base + i), 6)
    return {"hvn": [{"price": P(i), "strength": round(sm[i] / avg, 2)} for i in hv],
            "lvn": [{"price": P(i), "depth": round(sm[i] / avg, 2)} for i in lv]}


# ---------------------------------------------------------------- the engine
def analyze(bars: list[Candle], symbol: str, tf: str, vol_bars: list[Candle] | None = None, vol_source: str = "own") -> dict:
    if len(bars) < 30:
        return {"symbol": symbol, "tf": tf, "error": "not enough candles", "candles": len(bars)}
    step_sec = TF_SECONDS.get(tf, 300)
    vmap = {b.time: b.volume for b in (vol_bars or [])}
    vols = [vmap.get(b.time, 0.0) if vol_bars is not None else b.volume for b in bars]
    has_vol = sum(vols) > 0
    if not has_vol:
        vols = [1.0] * len(bars)                       # no volume anywhere: the volume profile becomes a time profile
        vol_source = "none (time-weighted)"
    at = _atr(bars) or (bars[-1].close * 0.001)
    sid, off = session_id(symbol)
    # bin: about a quarter of a typical candle's range, at least 0.02% of price
    med = sorted(b.high - b.low for b in bars[-300:])[len(bars[-300:]) // 2] or at
    g = Grid(min(b.low for b in bars), nice_bin(max(med / 4, bars[-1].close * 0.0002)))

    # sessions
    groups: dict = {}
    for i, b in enumerate(bars):
        groups.setdefault(sid(b.time), []).append(i)
    sessions = []
    for key in sorted(groups):
        ix = groups[key]
        sb, sv = [bars[i] for i in ix], [vols[i] for i in ix]
        t0 = sb[0].time
        vp, tpo = profile_of(sb, sv, g, t0)
        fh = [b for b in sb if b.time < t0 + 3600]
        sessions.append({"key": int(key), "date": dt.datetime.fromtimestamp(key * 86400, dt.timezone.utc).strftime("%Y-%m-%d"),
                         "start": t0, "end": sb[-1].time + step_sec, "last_t": sb[-1].time, "i0": ix[0], "i1": ix[-1],
                         "high": max(b.high for b in sb), "low": min(b.low for b in sb), "open": sb[0].open, "close": sb[-1].close,
                         "vp_lv": levels(g, poc_va(vp)), "tpo_lv": levels(g, poc_va(tpo)),
                         "tpo": tpo_detail(tpo, g, (min(b.low for b in fh), max(b.high for b in fh)) if fh else None),
                         "_vp": vp, "_tpo": tpo})
    cur = sessions[-1]
    # developing values for the last two sessions (candle by candle)
    for s in sessions[-2:]:
        vp, seen, dev = {}, {}, []
        for i in range(s["i0"], s["i1"] + 1):
            add_bar(vp, seen, g, bars[i], (bars[i].time - s["start"]) // TPO_SEC, vols[i])
            a = levels(g, poc_va(vp))
            tp = levels(g, poc_va({k: len(v) for k, v in seen.items()}))
            dev.append({"t": bars[i].time, "vp": a, "tpo": tp})
        s["developing"] = dev
    # naked POCs: earlier session POCs price has not traded through since
    for n, s in enumerate(sessions[:-1]):
        p = (s["vp_lv"] or {}).get("poc")
        later = bars[s["i1"] + 1:]
        s["naked_poc"] = bool(p is not None and later and not any(b.low <= p <= b.high for b in later))

    # composite (whole window) + nodes
    comp_vp, comp_tpo = {}, {}
    for s in sessions:
        for k2, v in s["_vp"].items():
            comp_vp[k2] = comp_vp.get(k2, 0.0) + v
        for k2, v in s["_tpo"].items():
            comp_tpo[k2] = comp_tpo.get(k2, 0) + v
    nd = nodes(comp_vp, g)
    seg = segment(bars, g, step_sec, at)
    # composite profile of every intraday balance (VP and TPO)
    for bl in seg["balances"]:
        vp, tp = profile_of(bars[bl["i0"]:bl["i1"] + 1], vols[bl["i0"]:bl["i1"] + 1], g, bars[bl["i0"]].time)
        bl["vp"], bl["tpo"] = levels(g, poc_va(vp)), levels(g, poc_va(tp))
    md = []
    for grp in multiday(sessions):
        vp, tp = {}, {}
        for x in grp:
            for k2, v in x["s"]["_vp"].items():
                vp[k2] = vp.get(k2, 0.0) + v
            for k2, v in x["s"]["_tpo"].items():
                tp[k2] = tp.get(k2, 0) + v
        lv = levels(g, poc_va(tp))
        md.append({"kind": "multi-day", "start": grp[0]["s"]["start"], "end": grp[-1]["s"]["end"], "sessions": len(grp),
                   "status": "developing" if grp[-1]["s"] is cur else "historical", "high": max(x["s"]["high"] for x in grp),
                   "low": min(x["s"]["low"] for x in grp), **(lv or {}), "vp": levels(g, poc_va(vp)), "tpo": lv})

    # failed auctions against the prior session's high/low (look above / below and fail)
    failed = list(seg["failed"])
    for prev, s in zip(sessions, sessions[1:]):
        sb = bars[s["i0"]:s["i1"] + 1]
        for side, lvl in (("high", prev["high"]), ("low", prev["low"])):
            for j, b in enumerate(sb):
                beyond = b.high > lvl if side == "high" else b.low < lvl
                if not beyond:
                    continue
                back = next((x for x in sb[j:j + FAIL_BARS + 1] if (x.close < lvl if side == "high" else x.close > lvl)), None)
                accepted = sum(1 for x in sb[j:j + ACCEPT] if (x.close > lvl if side == "high" else x.close < lvl)) >= ACCEPT
                if back is not None and not accepted:
                    ext = max(x.high for x in sb[j:sb.index(back) + 1]) if side == "high" else min(x.low for x in sb[j:sb.index(back) + 1])
                    pv = prev["vp_lv"] or prev["tpo_lv"] or {}
                    failed.append({"t": back.time, "t_probe": b.time, "side": side, "price": round(ext, 6), "ref": f"prior session {side}",
                                   "ref_price": round(lvl, 6), "target": pv.get("poc"), "target2": pv.get("val" if side == "high" else "vah")})
                break
    # a probe must go at least 0.15 ATR beyond its reference; one probe seen by two references is one failed auction
    failed = [f for f in failed if abs(f["price"] - f["ref_price"]) >= 0.15 * at or f["ref"] == "balance breakout"]
    failed.sort(key=lambda f: f["t"])
    merged: list[dict] = []
    for f in failed:
        m = next((x for x in merged if x["side"] == f["side"] and abs(x["t_probe"] - f["t_probe"]) <= 2 * step_sec), None)
        if m:
            if f["ref"] not in m["ref"]:
                m["ref"] += " + " + f["ref"]
            m["price"] = max(m["price"], f["price"]) if f["side"] == "high" else min(m["price"], f["price"])
        else:
            merged.append(dict(f))
    failed = merged

    last = bars[-1].close
    out = {"symbol": symbol, "tf": tf, "as_of": bars[-1].time + step_sec, "last": last, "atr": round(at, 6), "bin": g.step,
           "volume_source": vol_source, "candles": len(bars), "session_offset": off,
           "sessions": [{k: v for k, v in s.items() if not k.startswith("_") and k not in ("i0", "i1")} for s in sessions[-12:]],
           "composite": {"vp": levels(g, poc_va(comp_vp)), "tpo": levels(g, poc_va(comp_tpo)), "from": bars[0].time},
           "balances": [{k: v for k, v in b.items() if k not in ("i0", "i1")} for b in seg["balances"]][-25:],
           "multiday": md[-6:], "imbalances": [{k: v for k, v in x.items() if k not in ("i0", "i1")} for x in seg["imbalances"]][-25:],
           "failed": failed[-20:], "hvn": nd["hvn"], "lvn": nd["lvn"]}
    # profiles for drawing: composite (VP+TPO) and current session
    def rows(vp, tp):
        ks = sorted(set(vp) | set(tp))
        return [[round(g.base + k2 * g.step, 6), round(vp.get(k2, 0.0), 3), tp.get(k2, 0)] for k2 in ks]
    out["profile"] = {"composite": rows(comp_vp, comp_tpo), "session": rows(cur["_vp"], cur["_tpo"]), "step": g.step}
    out["confluence"] = confluence(out, at)
    out["projections"] = projections(out, at)
    out["state"], out["plan"] = read(out, at)
    return out


# ---------------------------------------------------------------- confluence, projections, the trading read
def confluence(o: dict, at: float) -> list[dict]:
    L = []

    def add(price, name, kind, w):
        if price is not None:
            L.append({"p": float(price), "name": name, "kind": kind, "w": w})
    ss = o["sessions"]
    for tag, s in (("today", ss[-1]), ("prev day", ss[-2] if len(ss) > 1 else None)):
        if not s:
            continue
        w = 1.0 if tag == "today" else 1.2
        for src, key in (("VP", "vp_lv"), ("TPO", "tpo_lv")):
            for lv in ("poc", "vah", "val"):
                add((s.get(key) or {}).get(lv), f"{tag} {src} {lv.upper()}", src, w * (1.3 if lv == "poc" else 1.0))
    for src in ("vp", "tpo"):
        for lv in ("poc", "vah", "val"):
            add((o["composite"].get(src) or {}).get(lv), f"composite {src.upper()} {lv.upper()}", src.upper(), 1.3)
    for b in o["multiday"][-3:] + [x for x in o["balances"] if x["status"] == "developing"] + o["balances"][-3:]:
        nm = "multi-day balance" if b["kind"] == "multi-day" else "balance"
        for src in ("vp", "tpo"):
            for lv in ("poc", "vah", "val"):
                add((b.get(src) or {}).get(lv), f"{nm} {src.upper()} {lv.upper()}", src.upper(), 1.1)
    for s in ss[:-1]:
        if s.get("naked_poc"):
            add(s["vp_lv"]["poc"], f"naked POC {s['date']}", "VP", 1.4)
    for h in o["hvn"]:
        add(h["price"], "HVN", "VP", 0.8)
    for x in o["lvn"]:
        add(x["price"], "LVN", "VP", 0.6)
    L.sort(key=lambda x: x["p"])
    tol = 0.35 * at
    zones, cur = [], []
    for x in L:
        if cur and x["p"] - cur[0]["p"] > tol:
            zones.append(cur)
            cur = []
        cur.append(x)
    if cur:
        zones.append(cur)
    out = []
    for z in zones:
        kinds = {x["kind"] for x in z}
        names = sorted({x["name"] for x in z})
        if len(names) < 2:
            continue
        score = sum(x["w"] for x in {x["name"]: x for x in z}.values()) * (1.5 if {"VP", "TPO"} <= kinds else 1.0)
        lo, hi = min(x["p"] for x in z), max(x["p"] for x in z)
        out.append({"lo": round(lo, 6), "hi": round(hi, 6), "mid": round((lo + hi) / 2, 6), "score": round(score, 2),
                    "vp_tpo": {"VP", "TPO"} <= kinds, "members": names, "side": "above" if lo > o["last"] else "below" if hi < o["last"] else "at price"})
    out.sort(key=lambda z: -z["score"])
    return out[:12]


def projections(o: dict, at: float) -> list[dict]:
    last = o["last"]
    bal = [b for b in o["balances"] if b["status"] == "historical"]
    dev = next((b for b in o["balances"] if b["status"] == "developing"), None)
    leg = next((x for x in reversed(o["imbalances"]) if x["status"] == "developing"), None)
    ref = dev or (bal[-1] if bal else None)
    areas = [{"lo": b["val"], "hi": b["vah"], "poc": b["poc"], "what": "historical balance"} for b in bal + o["multiday"] if b.get("val") is not None]
    areas += [{"lo": h["price"] - 0.25 * at, "hi": h["price"] + 0.25 * at, "poc": h["price"], "what": f"HVN ×{h['strength']}"} for h in o["hvn"]]

    def side(d, edge, height, why):
        beyond = [a for a in areas if (a["lo"] > edge if d > 0 else a["hi"] < edge)]
        beyond.sort(key=lambda a: (a["lo"] - edge) if d > 0 else (edge - a["hi"]))
        mm = {"lo": edge + (0.5 if d > 0 else -1.0) * height, "hi": edge + (1.0 if d > 0 else -0.5) * height}
        pick = beyond[0] if beyond and abs(beyond[0]["poc"] - edge) <= 2.5 * max(height, at) else None
        if pick:
            return {"dir": "up" if d > 0 else "down", "lo": round(pick["lo"], 6), "hi": round(pick["hi"], 6), "poc": round(pick["poc"], 6),
                    "basis": f"next {pick['what']} {'above' if d > 0 else 'below'}", "trigger": why, "measured": {k: round(v, 6) for k, v in mm.items()}}
        return {"dir": "up" if d > 0 else "down", "lo": round(min(mm.values()), 6), "hi": round(max(mm.values()), 6), "poc": round((mm["lo"] + mm["hi"]) / 2, 6),
                "basis": "measured move (height of the balance left)", "trigger": why}
    out = []
    if leg and dev is None:
        b = bal[-1] if bal else None
        h = (b["vah"] - b["val"]) if b else 2 * at
        d = 1 if leg["dir"] == "bull" else -1
        edge = (b["vah"] if d > 0 else b["val"]) if b else leg["frm"]
        out.append(side(d, max(edge, last) if d > 0 else min(edge, last), h, f"{leg['dir']}ish imbalance in progress"))
    elif ref:
        h = max(ref["vah"] - ref["val"], at)
        out.append(side(1, ref["vah"], h, f"acceptance above {ref['vah']:g} (3 closes)"))
        out.append(side(-1, ref["val"], h, f"acceptance below {ref['val']:g} (3 closes)"))
    return out


def read(o: dict, at: float) -> tuple[dict, list[dict]]:
    last = o["last"]
    ss = o["sessions"]
    cur, prev = ss[-1], (ss[-2] if len(ss) > 1 else None)
    dev = next((b for b in o["balances"] if b["status"] == "developing"), None)
    leg = next((x for x in reversed(o["imbalances"]) if x["status"] == "developing"), None)
    va = cur.get("vp_lv") or cur.get("tpo_lv") or {}
    pva = (prev or {}).get("vp_lv") or {}

    def loc(v):
        if not v:
            return "?"
        return "above value" if last > v["vah"] else "below value" if last < v["val"] else "inside value"
    st = {"phase": "balance" if dev else "imbalance" if leg else "transition", "today": loc(va), "vs_prev_day": loc(pva),
          "open_vs_prev": "?",
          "balance": dev and {k: dev[k] for k in ("vah", "val", "poc", "high", "low", "start", "bars")},
          "imbalance": leg and {k: leg[k] for k in ("dir", "frm", "to", "size_atr", "start")}}
    if pva and cur.get("open") is not None:
        o_ = cur["open"]
        st["open_vs_prev"] = "opened above prior value" if o_ > pva["vah"] else "opened below prior value" if o_ < pva["val"] else "opened inside prior value"
    recent_fail = [f for f in o["failed"] if f["t"] >= cur["start"]]
    st["failed_today"] = recent_fail[-3:]
    tp = cur.get("tpo") or {}
    st["poor_high"], st["poor_low"] = tp.get("poor_high"), tp.get("poor_low")
    naked = [s for s in ss[:-1] if s.get("naked_poc")]
    st["naked_pocs"] = [{"date": s["date"], "poc": s["vp_lv"]["poc"]} for s in naked[-4:]]
    plan = []
    r = lambda x: round(x, 2)
    if recent_fail:
        f = recent_fail[-1]
        d = -1 if f["side"] == "high" else 1
        plan.append({"setup": f"Failed auction {'above' if d < 0 else 'below'} {f['ref']}", "bias": "short" if d < 0 else "long",
                     "entry": f"{'below' if d < 0 else 'above'} {r(f['ref_price'])} (back inside)", "stop": r(f["price"] + (0.15 if d < 0 else -0.15) * at),
                     "targets": [x for x in (f.get("target"), f.get("target2")) if x is not None],
                     "why": "Look above/below and fail: the market rejected that price and should rotate back through value."})
    if dev:
        h = dev["vah"] - dev["val"]
        # stop just beyond the balance, but never further than half the value height past the edge (a spike that
        # started the balance must not set the stop)
        s_hi = min(dev["high"], dev["vah"] + 0.5 * h) + 0.2 * at
        s_lo = max(dev["low"], dev["val"] - 0.5 * h) - 0.2 * at
        plan.append({"setup": "Inside balance: fade the edges (responsive)", "bias": "two-sided",
                     "entry": f"short near VAH {r(dev['vah'])} / long near VAL {r(dev['val'])}", "stop": f"{r(s_hi)} / {r(s_lo)}",
                     "targets": [r(dev["poc"]), r(dev["val"])] if last >= dev["poc"] else [r(dev["poc"]), r(dev["vah"])],
                     "why": "In balance, buyers and sellers agree on value: edges get rejected, the POC acts as a magnet. Avoid trading in the middle."})
        prj = o["projections"]
        if prj:
            u = next((p for p in prj if p["dir"] == "up"), None)
            dn = next((p for p in prj if p["dir"] == "down"), None)
            plan.append({"setup": "Breakout of balance (initiative) – only on acceptance", "bias": "with the break",
                         "entry": f"after 3 closes above {r(dev['vah'])} buy the retest of it / after 3 closes below {r(dev['val'])} sell the retest",
                         "stop": f"back inside value ({r(dev['poc'])})", "targets": [x for x in ((u or {}).get("poc"), (dn or {}).get("poc")) if x is not None],
                         "why": f"Height of value {r(h)}: acceptance outside means the auction is looking for a new balance (projected zones)."})
    elif leg:
        d = 1 if leg["dir"] == "bull" else -1
        prj = (o["projections"] or [None])[0]
        lastbal = next((b for b in reversed(o["balances"]) if b["status"] == "historical"), None)
        edge = (lastbal["vah"] if d > 0 else lastbal["val"]) if lastbal else leg["frm"]
        plan.append({"setup": f"{'Bullish' if d > 0 else 'Bearish'} imbalance: trade with it (initiative)", "bias": "long" if d > 0 else "short",
                     "entry": f"pullback to the broken edge {r(edge)} or a single-print / LVN zone", "stop": r(edge - d * 0.5 * at),
                     "targets": [prj["lo"] if d > 0 else prj["hi"], prj["poc"]] if prj else [],
                     "why": "Price left value with acceptance: the old edge should now hold, and the market travels to the next balance area."})
    if st["poor_high"] or st["poor_low"]:
        plan.append({"setup": f"Unfinished auction: poor {'high' if st['poor_high'] else 'low'} {r(cur['high'] if st['poor_high'] else cur['low'])}",
                     "bias": "magnet", "entry": "—", "stop": "—", "targets": [r(cur["high"] if st["poor_high"] else cur["low"])],
                     "why": "No excess at the extreme (2+ TPOs): price usually comes back to finish the auction. Do not fade it tightly."})
    for n in st["naked_pocs"][-2:]:
        if abs(n["poc"] - last) <= 4 * at:
            plan.append({"setup": f"Naked POC {n['date']} at {r(n['poc'])}", "bias": "magnet", "entry": "—", "stop": "—", "targets": [r(n["poc"])],
                         "why": "An untested prior POC often attracts price; good first target, or a level to fade into."})
    return st, plan


# ---------------------------------------------------------------- gathering (needs the running app)
async def compute(symbol: str, tf: str = "", days: int = 10) -> dict:
    from . import data as D
    symbol = symbol.strip().upper()
    india = symbol.split(":", 1)[0] in ("NSE", "BSE", "MCX")
    tf = tf or ("5m" if india else "15m")
    if tf not in ("1m", "3m", "5m", "15m", "30m"):
        tf = "5m"
    per_day = (375 if india else 1440) * 60 // TF_SECONDS[tf]
    n = max(200, min(2000, per_day * max(3, min(30, days)) + 10))
    key = (symbol, tf, n)
    hit = _cache.get(key)
    ttl = 300 if india else 60                        # FYERS free plan: 5,000 data requests a day, so India refreshes every 5 minutes
    if hit and time.time() - hit[0] < ttl:
        return hit[1]
    fut = INDEX_FUT.get(symbol)
    if fut:
        (bars, q), fv = await asyncio.gather(D.candles(symbol, tf, n), _try(D.candles(fut, tf, n)))
        vol_bars, src = (fv[0], f"front-month future ({fut})") if fv else (None, "none (future unavailable)")
    else:
        bars, q = await D.candles(symbol, tf, n)
        vol_bars, src = None, "own volume"
    out = analyze(bars, symbol, tf, vol_bars, src)
    out["source"] = q.get("source")
    out["method"] = __doc__
    _cache[key] = (time.time(), out)
    return out


async def _try(coro):
    try:
        return await coro
    except Exception:                                 # noqa: BLE001 - volume is optional
        return None

backend/lab/candle.py:
"""Candles for the Signal Lab: one type, validation and resampling.

A candle's `time` is the epoch second its interval STARTS (UTC). Only closed candles are analysed: the candle still
forming is dropped by `closed_only`, so nothing computed here can change after the fact (no repainting).
"""
from __future__ import annotations

import datetime as dt
from dataclasses import dataclass, asdict

IST = dt.timezone(dt.timedelta(hours=5, minutes=30))
TF_SECONDS = {"1m": 60, "3m": 180, "5m": 300, "15m": 900, "30m": 1800, "1h": 3600, "4h": 14400, "1d": 86400, "1w": 604800}


@dataclass(frozen=True)
class Candle:
    time: int
    open: float
    high: float
    low: float
    close: float
    volume: float = 0.0

    def to_dict(self) -> dict:
        return asdict(self)


def from_rows(rows) -> list[Candle]:
    """[epoch_s, o, h, l, c, v] rows -> Candles (bad rows skipped)."""
    out = []
    for r in rows or []:
        try:
            out.append(Candle(int(r[0]), float(r[1]), float(r[2]), float(r[3]), float(r[4]), float(r[5] if len(r) > 5 and r[5] is not None else 0)))
        except (TypeError, ValueError, IndexError):
            continue
    return out


def validate(bars: list[Candle], step: int, now: float | None = None, session_gap_ok: bool = True) -> tuple[list[Candle], dict]:
    """Sort, drop duplicates and impossible candles, and report gaps and staleness.

    Returns the cleaned candles and a quality report: duplicates removed, bad candles removed (high < low, close or
    open outside the range, non-positive prices), gaps (missing candles inside what should be continuous trading;
    gaps longer than 6 hours are treated as session breaks, not missing data) and whether the last candle is stale
    (older than 3 intervals, measured from `now`)."""
    seen: dict[int, Candle] = {}
    dupes = bad = 0
    for b in bars:
        if not (b.low > 0 and b.high >= b.low and b.low <= b.open <= b.high and b.low <= b.close <= b.high):
            bad += 1
            continue
        if b.time in seen:
            dupes += 1
        seen[b.time] = b
    clean = [seen[t] for t in sorted(seen)]
    gaps = []
    for a, b in zip(clean, clean[1:]):
        d = b.time - a.time
        if d > step and (not session_gap_ok or d <= 6 * 3600) and step < 86400:
            gaps.append({"after": a.time, "missing": d // step - 1})
    stale = None
    if now is not None and clean:
        stale = now - (clean[-1].time + step) > 3 * step
    return clean, {"candles": len(clean), "duplicates_removed": dupes, "bad_removed": bad,
                   "gaps": len(gaps), "missing_candles": sum(g["missing"] for g in gaps), "stale": stale,
                   "first": clean[0].time if clean else None, "last": clean[-1].time if clean else None}


def closed_only(bars: list[Candle], step: int, now: float) -> list[Candle]:
    """Drop the candle that has not closed yet."""
    return [b for b in bars if b.time + step <= now]


def bucket(t: int, tf: str, anchor_min: int = 0) -> int:
    """Start of the `tf` bucket that contains epoch second `t`. Intraday buckets are aligned to the session open
    (`anchor_min` minutes after midnight IST, e.g. 555 for 09:15 NSE) so 1h candles run 09:15-10:15. Daily and
    weekly buckets follow the IST calendar for Indian markets (anchor_min > 0) and UTC otherwise."""
    s = TF_SECONDS[tf]
    if tf == "1w":
        tz = IST if anchor_min else dt.timezone.utc
        d = dt.datetime.fromtimestamp(t, tz).date()
        monday = d - dt.timedelta(days=d.weekday())
        return int(dt.datetime(monday.year, monday.month, monday.day, tzinfo=tz).timestamp())
    if tf == "1d":
        tz = IST if anchor_min else dt.timezone.utc
        d = dt.datetime.fromtimestamp(t, tz).date()
        return int(dt.datetime(d.year, d.month, d.day, tzinfo=tz).timestamp())
    if anchor_min:
        local = dt.datetime.fromtimestamp(t, IST)
        day0 = int(dt.datetime(local.year, local.month, local.day, tzinfo=IST).timestamp())
        start = day0 + anchor_min * 60
        if t < start:
            return t - (t - day0) % s
        return start + ((t - start) // s) * s
    return t - t % s


def resample(bars: list[Candle], tf: str, anchor_min: int = 0) -> list[Candle]:
    """Aggregate candles into `tf` candles. The last bucket may be incomplete: callers that need closed candles
    pass the result through `closed_only` with the target step."""
    out: list[Candle] = []
    cur = None
    for b in bars:
        k = bucket(b.time, tf, anchor_min)
        if cur and cur[0] == k:
            cur[2] = max(cur[2], b.high)
            cur[3] = min(cur[3], b.low)
            cur[4] = b.close
            cur[5] += b.volume
        else:
            if cur:
                out.append(Candle(*cur))
            cur = [k, b.open, b.high, b.low, b.close, b.volume]
    if cur:
        out.append(Candle(*cur))
    return out


def ist(t: int) -> dt.datetime:
    return dt.datetime.fromtimestamp(t, IST)

backend/lab/costs.py:
"""Transaction costs, slippage and spread used by the backtester and the paper ledger.

India (NSE/BSE/MCX), statutory rates as published by the exchanges/SEBI (verify before relying on them; they change):
  brokerage           Rs 20 per executed order (discount-broker flat fee; setting)
  STT                 equity intraday 0.025% sell; futures 0.02% sell; options 0.1% of premium sell
  exchange txn        equity 0.00297%; futures 0.00173%; options 0.03503% of premium; MCX futures 0.0021%
  SEBI fee            Rs 10 per crore of turnover
  stamp duty          equity intraday 0.003% buy; futures 0.002% buy; options 0.003% buy
  GST                 18% on brokerage + exchange txn + SEBI fee
Index spot symbols (NIFTY50-INDEX etc.) cannot be traded; their backtests use FUTURES costs as a proxy and say so.
Crypto: taker fee in basis points per side (Delta Exchange India 5 bps default; Shark: same setting), funding
  payments are NOT modelled (noted in results).
US / forex (Yahoo data): spread + commission settings only.
Slippage: `slip_bps` per side on top of half the assumed spread, applied against the trade.
"""
from __future__ import annotations

DEFAULTS = {
    "brokerage_inr": 20.0, "crypto_fee_bps": 5.0, "us_comm_bps": 1.0,
    "slip_bps": {"NSE": 2.0, "FNO": 2.0, "MCX": 2.0, "SHARK": 3.0, "DELTAF": 3.0, "DELTA": 10.0, "BINANCE": 2.0, "YF": 2.0},
    "spread_bps": {"NSE": 2.0, "FNO": 1.0, "MCX": 2.0, "SHARK": 2.0, "DELTAF": 2.0, "DELTA": 50.0, "BINANCE": 1.0, "YF": 2.0},
}
INDIA = {
    "equity": {"stt_sell": 0.00025, "txn": 0.0000297, "stamp_buy": 0.00003},
    "futures": {"stt_sell": 0.0002, "txn": 0.0000173, "stamp_buy": 0.00002},
    "options": {"stt_sell": 0.001, "txn": 0.0003503, "stamp_buy": 0.00003},
    "mcx": {"stt_sell": 0.0001, "txn": 0.000021, "stamp_buy": 0.00002},
}


def instrument_kind(symbol: str, market: str) -> tuple[str, str | None]:
    s = symbol.upper()
    if market == "MCX":
        return "mcx", None
    if market in ("NSE", "FNO"):
        if s.endswith("-EQ") or s.endswith("-BE"):
            return "equity", None
        if s.endswith("CE") or s.endswith("PE"):
            return "options", None
        if s.endswith("-INDEX"):
            return "futures", "Index spot is not tradable: futures costs used as a proxy"
        return "futures", None
    return "other", None


def slip_price(price: float, side: int, market: str, cfg: dict | None = None) -> float:
    """Price after slippage + half-spread, moved against a trade whose order side is +1 buy / -1 sell."""
    c = cfg or DEFAULTS
    bps = c["slip_bps"].get(market, 2.0) + c["spread_bps"].get(market, 2.0) / 2
    return price * (1 + side * bps / 10000)


def round_trip(symbol: str, market: str, qty: float, entry: float, exit_: float, long: bool, cfg: dict | None = None) -> float:
    """Total fees and taxes for one entry + one exit (currency of the instrument)."""
    c = cfg or DEFAULTS
    buy_px, sell_px = (entry, exit_) if long else (exit_, entry)
    buy_v, sell_v = abs(qty) * buy_px, abs(qty) * sell_px
    kind, _ = instrument_kind(symbol, market)
    if kind in INDIA:
        r = INDIA[kind]
        brk = 2 * c["brokerage_inr"]
        if kind == "equity":
            brk = min(brk, 0.0003 * (buy_v + sell_v))
        txn = r["txn"] * (buy_v + sell_v)
        sebi = (buy_v + sell_v) * 10 / 1e7
        return brk + r["stt_sell"] * sell_v + txn + sebi + r["stamp_buy"] * buy_v + 0.18 * (brk + txn + sebi)
    if market in ("SHARK", "DELTAF", "DELTA", "BINANCE"):
        return c["crypto_fee_bps"] / 10000 * (buy_v + sell_v)
    return c["us_comm_bps"] / 10000 * (buy_v + sell_v)

backend/lab/custom.py:
"""Strategy workbench: your own rule-based strategies, built from the same market fields the ML model uses.

A custom strategy is data (stored in the Lab setting "custom_strategies"), never code:
  {"key": "custom_<slug>", "name", "description", "direction": "long" | "short" | "both",
   "conditions": [{"field": "rsi_dir", "op": ">", "value": 5}, {"field": "regime", "op": "in", "value": ["weak_bull"]}, ...],
   "stop": {"type": "swing" | "atr", "atr_mult": 1.5}, "stop_buffer_atr": 0.1, "min_rr": 1.5,
   "regimes": ["weak_bull", ...]   # regimes it suits (the agent declines it elsewhere)
   "status": "draft" | "approved"}
Every field is measured "in the trade's direction" (see mlfeat.DESCRIBE), so one rule set works for longs and shorts:
"ema50_dir > 0" means price is on the trade's side of EMA50. A missing value (e.g. volume on an index) fails the rule.
It then goes through the normal Lab pipeline: build_setup (stop buffer, targets from liquidity, minimum reward:risk),
scoring, backtests, the ML filter and the Risk Guardian. A draft is only backtested; the agent trades it only after you
approve it. Nothing here can change risk limits.
"""
from __future__ import annotations

import re

from . import mlfeat as MF
from . import regime as RG
from . import scoring as SC
from . import store
from . import strategies as ST

RULE_FIELDS = [f for f in MF.NUMERIC if f not in ("score", "rr", "rr_t1", "stop_atr")] + ["regime", "volatility", "market"]
OPS = (">", ">=", "<", "<=", "==", "!=", "between", "in", "not in")
_loaded = {"sig": None, "keys": []}


def _fields(F, i: int, d: int, ctx: dict) -> dict:
    cache = F.__dict__.setdefault("_wb_cache", {})
    k = (i, d)
    if k not in cache:
        ds = SC.directional(F, i, ctx)
        if len(cache) > 4000:
            cache.clear()
        cache[k] = MF.features(F, i, ctx, ds, {"direction": "LONG" if d > 0 else "SHORT", "strategy": "custom"})
    return cache[k]


def check(cond: dict, v) -> bool:
    op, x = cond.get("op"), cond.get("value")
    if v is None:
        return False
    try:
        if op == "in":
            return v in (x or [])
        if op == "not in":
            return v not in (x or [])
        if op == "==":
            return v == x if isinstance(v, str) else float(v) == float(x)
        if op == "!=":
            return v != x if isinstance(v, str) else float(v) != float(x)
        if op == "between":
            lo, hi = float(x[0]), float(x[1])
            return lo <= float(v) <= hi
        v, x = float(v), float(x)
        return {">": v > x, ">=": v >= x, "<": v < x, "<=": v <= x}[op]
    except (TypeError, ValueError, KeyError, IndexError):
        return False


def make_fn(spec: dict):
    def fn(F, i, d, ctx):
        want = spec.get("direction", "both")
        if (want == "long" and d < 0) or (want == "short" and d > 0):
            return None
        f = _fields(F, i, d, ctx)
        for c in spec.get("conditions") or []:
            if not check(c, f.get(c.get("field"))):
                return None
        st = spec.get("stop") or {"type": "swing"}
        at = F.atr[i]
        if not at:
            return None
        cl = F.c[i]
        if st.get("type") == "atr":
            anchor = cl - d * float(st.get("atr_mult", 1.5)) * at
        else:
            sw = F.swings_at(F.t[i], "low" if d > 0 else "high", True)
            sw = [x for x in sw if (x.price < cl if d > 0 else x.price > cl)]
            if not sw:
                return None
            anchor = sw[-1].price
        rs = [f"{c['field']} {c['op']} {c.get('value')} (now {f.get(c['field']) if not isinstance(f.get(c['field']), float) else round(f.get(c['field']), 2)})"
              for c in spec.get("conditions") or []]
        return {"anchor": anchor, "reasons": [f"Your rule '{spec.get('name')}'"] + rs}
    return fn


def validate(spec: dict) -> dict:
    """Clean a submitted strategy, or raise ValueError with the reason."""
    name = str(spec.get("name") or "").strip()[:60]
    if not name:
        raise ValueError("give the strategy a name")
    slug = re.sub(r"[^a-z0-9]+", "_", name.lower()).strip("_")[:30] or "rule"
    key = spec.get("key") if str(spec.get("key") or "").startswith("custom_") else f"custom_{slug}"
    if key in ST.META and not key.startswith("custom_"):
        raise ValueError("that name clashes with a built-in strategy")
    conds = []
    for c in spec.get("conditions") or []:
        f, op = c.get("field"), c.get("op")
        if f not in RULE_FIELDS:
            raise ValueError(f"unknown field {f!r}")
        if op not in OPS:
            raise ValueError(f"unknown operator {op!r}")
        v = c.get("value")
        if op in ("in", "not in"):
            v = [str(x) for x in (v if isinstance(v, list) else str(v).split(","))if str(x).strip()]
            v = [x.strip() for x in v]
        elif op == "between":
            if not isinstance(v, list) or len(v) != 2:
                raise ValueError(f"{f}: 'between' needs two numbers")
            v = [float(v[0]), float(v[1])]
        elif f in ("regime", "volatility", "market"):
            v = str(v)
        else:
            v = float(v)
        conds.append({"field": f, "op": op, "value": v})
    if not conds:
        raise ValueError("add at least one condition")
    st = spec.get("stop") or {}
    stop = {"type": "atr" if st.get("type") == "atr" else "swing", "atr_mult": min(4.0, max(0.3, float(st.get("atr_mult") or 1.5)))}
    regs = [r for r in (spec.get("regimes") or []) if r in RG.SUITS]
    return {"key": key, "name": name, "description": str(spec.get("description") or "")[:300],
            "direction": spec.get("direction") if spec.get("direction") in ("long", "short", "both") else "both",
            "conditions": conds, "stop": stop, "stop_buffer_atr": min(1.0, max(0.0, float(spec.get("stop_buffer_atr", 0.1)))),
            "min_rr": min(5.0, max(1.0, float(spec.get("min_rr", 1.5)))), "regimes": regs,
            "status": "approved" if spec.get("status") == "approved" else "draft"}


def all_specs() -> list[dict]:
    return store.get_setting("custom_strategies") or []


def save_all(specs: list[dict]) -> None:
    store.set_setting("custom_strategies", specs)
    ensure(force=True)


def ensure(force: bool = False) -> list[str]:
    """Register the stored custom strategies with the Lab (idempotent; cheap when nothing changed)."""
    try:
        specs = all_specs()
    except Exception:                                     # noqa: BLE001 - no database yet
        specs = []
    sig = repr(specs)
    if not force and sig == _loaded["sig"]:
        return _loaded["keys"]
    for k in _loaded["keys"]:                             # unregister the previous set
        ST.MODULES.pop(k, None)
        ST.META.pop(k, None)
        ST.PARAMS.pop(k, None)
        for lst in RG.SUITS.values():
            while k in lst:
                lst.remove(k)
    keys = []
    for sp in specs:
        k = sp["key"]
        ST.MODULES[k] = make_fn(sp)
        conds = "; ".join(f"{c['field']} {c['op']} {c['value']}" for c in sp["conditions"])
        ST.META[k] = (f"★ {sp['name']}", (sp.get("description") or "Your rule") + f" [{conds}]")
        ST.PARAMS[k] = {"enabled": sp.get("status") == "approved", "stop_buffer_atr": sp.get("stop_buffer_atr", 0.1),
                        "min_rr": sp.get("min_rr", 1.5), "min_avg_volume": 0, "custom": True}
        for r in sp.get("regimes") or []:
            if r in RG.SUITS and k not in RG.SUITS[r]:
                RG.SUITS[r].append(k)
        keys.append(k)
    _loaded.update(sig=sig, keys=keys)
    return keys

backend/lab/ict.py:
"""ICT / SMC layer on top of smc.py (swings, BOS/CHoCH, sweeps, FVGs). Every concept below has an exact rule, its
parameters at the top, and a timestamp; all of it runs on closed candles only.

Definitions
- Displacement candle: body >= DISP_BODY_ATR x ATR(14) and body >= DISP_BODY_SHARE of its range.
- MSS (market structure shift): a CHoCH whose breaking candle, or one of the DISP_LOOKBACK candles before it, is a
  displacement candle in the break's direction.
- Internal / external structure: smc.py run with swing span INTERNAL_SPAN (2) / EXTERNAL_SPAN (5).
- Protected high/low: in a bullish external trend, the swing low the latest bullish break came from (the lowest
  swing low between the previous break and this one); its loss is the CHoCH level. Mirror for bearish.
- Order block (bullish): for a bullish BOS/CHoCH, the last down-close candle (close < open) in the
  OB_SEARCH candles before the displacement leg began. Zone = that candle's low..high. Bearish mirror.
  Mitigated: a later candle trades into the zone. Breaker: a later candle CLOSES beyond the far side (bullish OB
  closed below its low), which flips it into a bearish breaker block. Mitigation block: an OB that was mitigated
  and then price closed away in the OB's direction (the zone held).
  Volume confirmation: the breaking leg's volume >= OB_VOL_MULT x the 20-candle average.
- Inverse FVG: an FVG that a candle CLOSES through (bullish FVG closed below its bottom) flips polarity.
- Consequent encroachment (CE): the FVG's midpoint.
- FVG quality 0-100: size vs ATR (40), displacement of the middle candle (30), volume (15), untouched (15).
- Equal highs/lows: two confirmed swing highs (lows) within EQ_TOL_ATR x ATR of each other, not yet traded through.
- Dealing range: the latest external swing high and low. Premium above its 50% (equilibrium), discount below.
- OTE: 0.62-0.79 retracement of the latest impulse leg (swing to the BOS candle's extreme); the "sweet spot" 0.705.
- Asian range: high/low of the Asian session (00:00-06:00 UTC = 05:30-11:30 IST) of the current UTC day.
- Kill zones: London open 07:00-10:00 UTC, New York open 12:00-15:00 UTC (12:00-15:00 UTC in winter means
  07:00-10:00 New York time; US daylight saving is applied), London close 15:00-17:00 UTC; for NSE/BSE: opening
  drive 09:15-10:15 IST and closing hour 14:30-15:30 IST.
- Judas swing: in the first kill zone of the day, price trades beyond one side of the Asian range (or for NSE the
  opening range of the first 15 minutes) and then a candle closes back beyond the session open the other way.
- Power of three (AMD): accumulation = Asian range (or NSE opening 30 minutes); manipulation = the first sweep of
  one side of it; distribution = a later close beyond the opposite side. The current phase is reported.
- SMT divergence: two correlated instruments over the same window; one sweeps its previous swing high (low) while
  the other fails to, -> bearish (bullish) SMT, timestamped at the sweeping candle.
- Inducement: the latest internal swing (span 2) between price and the nearest unmitigated order block / FVG in
  the retracement direction; "taken" once swept.
"""
from __future__ import annotations

import datetime as dt
from dataclasses import asdict, dataclass

from .candle import Candle
from .ind import atr_list, sma
from . import smc as S

DISP_BODY_ATR = 1.2
DISP_BODY_SHARE = 0.6
DISP_LOOKBACK = 3
INTERNAL_SPAN = 2
EXTERNAL_SPAN = 5
OB_SEARCH = 10
OB_VOL_MULT = 1.5
EQ_TOL_ATR = 0.1


def displacement(bars: list[Candle]) -> list[int]:
    """+1 bullish displacement, -1 bearish, 0 none, per candle."""
    a = atr_list(bars)
    out = []
    for i, b in enumerate(bars):
        body, rng = abs(b.close - b.open), b.high - b.low
        ok = a[i] is not None and rng > 0 and body >= DISP_BODY_ATR * a[i] and body >= DISP_BODY_SHARE * rng
        out.append((1 if b.close > b.open else -1) if ok else 0)
    return out


@dataclass
class OrderBlock:
    direction: str  # bullish | bearish
    top: float
    bottom: float
    time: int  # the order-block candle
    break_time: int  # the BOS/CHoCH that created it
    break_type: str
    volume_confirmed: bool
    mitigated_time: int | None = None
    breaker_time: int | None = None  # closed through: now a breaker of the opposite direction
    held_time: int | None = None  # mitigated, then closed away in its direction (mitigation block)

    @property
    def state(self) -> str:
        if self.breaker_time:
            return "breaker"
        if self.held_time:
            return "mitigation block"
        if self.mitigated_time:
            return "mitigated"
        return "fresh"


def order_blocks(bars: list[Candle], rep: S.SmcReport) -> list[OrderBlock]:
    idx = {b.time: i for i, b in enumerate(bars)}
    vavg = sma([b.volume for b in bars], 20)
    out: list[OrderBlock] = []
    for br in rep.structure:
        k = idx.get(br.time)
        if k is None:
            continue
        bull = br.direction == "bullish"
        # start of the leg: walk back while candles move with the break
        j = k
        while j > 0 and (bars[j].close > bars[j].open) == bull and k - j < OB_SEARCH:
            j -= 1
        ob = None
        for m in range(j, max(-1, j - OB_SEARCH), -1):
            if (bars[m].close < bars[m].open) if bull else (bars[m].close > bars[m].open):
                ob = m
                break
        if ob is None:
            continue
        leg_vol = sum(b.volume for b in bars[ob + 1:k + 1]) / max(1, k - ob)
        vc = bool(vavg[k] and leg_vol >= OB_VOL_MULT * vavg[k])
        o = OrderBlock("bullish" if bull else "bearish", bars[ob].high, bars[ob].low, bars[ob].time, br.time, br.type, vc)
        for b in bars[k + 1:]:
            inside = b.low <= o.top and b.high >= o.bottom
            if o.mitigated_time is None and inside:
                o.mitigated_time = b.time
            if (b.close < o.bottom) if bull else (b.close > o.top):
                o.breaker_time = b.time
                break
            if o.mitigated_time and o.held_time is None and b.time > o.mitigated_time and ((b.close > o.top) if bull else (b.close < o.bottom)):
                o.held_time = b.time
        out.append(o)
    return out


def fvg_extras(bars: list[Candle], rep: S.SmcReport) -> list[dict]:
    """FVGs with CE, inverse-FVG flips and a 0-100 quality score."""
    a = atr_list(bars)
    idx = {b.time: i for i, b in enumerate(bars)}
    vavg = sma([b.volume for b in bars], 20)
    disp = displacement(bars)
    out = []
    for g in rep.fvgs:
        i = idx.get(g.time)
        if i is None:
            continue
        size = g.top - g.bottom
        at = a[i] or size or 1
        mid = bars[i]
        q = min(40.0, 40 * size / (at * 1.0))
        q += 30 if disp[i] == (1 if g.direction == "bullish" else -1) else 10 if abs(mid.close - mid.open) > 0.6 * (mid.high - mid.low or 1) else 0
        q += 15 if vavg[i] and mid.volume >= 1.5 * vavg[i] else 5 if vavg[i] and mid.volume >= vavg[i] else 0
        q += 15 if not g.touched else 0
        inv = None
        for b in bars[idx.get(g.created_time, i) + 1:]:
            if (b.close < g.bottom) if g.direction == "bullish" else (b.close > g.top):
                inv = b.time
                break
        d = asdict(g)
        d.update(ce=(g.top + g.bottom) / 2, quality=round(min(100.0, q)), inverse_time=inv,
                 inverse_direction=("bearish" if g.direction == "bullish" else "bullish") if inv else None)
        out.append(d)
    return out


def mss(bars: list[Candle], rep: S.SmcReport) -> list[dict]:
    idx = {b.time: i for i, b in enumerate(bars)}
    disp = displacement(bars)
    out = []
    for br in rep.structure:
        if br.type != "CHoCH":
            continue
        k = idx.get(br.time)
        if k is None:
            continue
        want = 1 if br.direction == "bullish" else -1
        if any(disp[j] == want for j in range(max(0, k - DISP_LOOKBACK), k + 1)):
            out.append({"direction": br.direction, "level": br.level, "time": br.time})
    return out


def protected_levels(rep: S.SmcReport) -> dict:
    """The swing the latest external break came from; losing it is the CHoCH level."""
    if not rep.structure:
        return {}
    last = rep.structure[-1]
    prev_t = rep.structure[-2].time if len(rep.structure) > 1 else 0
    kind = "low" if last.direction == "bullish" else "high"
    cands = [s for s in rep.swings if s.kind == kind and prev_t <= s.time <= last.time]
    if not cands:
        return {}
    s = min(cands, key=lambda x: x.price) if kind == "low" else max(cands, key=lambda x: x.price)
    return {"protected_" + kind: s.price, "time": s.time, "trend": last.direction}


def equal_levels(bars: list[Candle], rep: S.SmcReport) -> list[dict]:
    a = atr_list(bars)
    tol = (next((x for x in reversed(a) if x), None) or 0) * EQ_TOL_ATR
    out = []
    for kind, live in (("high", rep.buy_side), ("low", rep.sell_side)):
        pts = sorted(live, key=lambda s: s.price)
        for x, y in zip(pts, pts[1:]):
            if tol and abs(x.price - y.price) <= tol:
                out.append({"kind": "equal " + kind + "s", "price": (x.price + y.price) / 2, "times": [x.time, y.time],
                            "side": "buy" if kind == "high" else "sell"})
    return out


def dealing_range(rep: S.SmcReport, price: float) -> dict:
    hs = [s for s in rep.swings if s.kind == "high"]
    ls = [s for s in rep.swings if s.kind == "low"]
    if not hs or not ls:
        return {}
    hi, lo = hs[-1].price, ls[-1].price
    if hi <= lo:
        return {}
    eq = (hi + lo) / 2
    pct = 100 * (price - lo) / (hi - lo)
    zone = "premium" if price > eq else "discount" if price < eq else "equilibrium"
    return {"high": hi, "low": lo, "equilibrium": eq, "position_pct": round(pct, 1), "zone": zone,
            "high_time": hs[-1].time, "low_time": ls[-1].time}


def ote(bars: list[Candle], rep: S.SmcReport) -> dict:
    """OTE of the latest impulse: from the swing before the last break to the break leg's extreme."""
    if not rep.structure:
        return {}
    br = rep.structure[-1]
    idx = {b.time: i for i, b in enumerate(bars)}
    k = idx.get(br.time)
    if k is None:
        return {}
    bull = br.direction == "bullish"
    kind = "low" if bull else "high"
    prev = [s for s in rep.swings if s.kind == kind and s.time <= br.time]
    if not prev:
        return {}
    start = prev[-1].price
    ext = max(b.high for b in bars[k:]) if bull else min(b.low for b in bars[k:])
    rng = ext - start
    lvl = lambda r: ext - r * rng
    return {"direction": br.direction, "leg_start": start, "leg_end": ext, "ote_top": lvl(0.62), "ote_bottom": lvl(0.79),
            "sweet_spot": lvl(0.705), "fib_50": lvl(0.5), "time": br.time} if bull else \
           {"direction": br.direction, "leg_start": start, "leg_end": ext, "ote_top": lvl(0.79), "ote_bottom": lvl(0.62),
            "sweet_spot": lvl(0.705), "fib_50": lvl(0.5), "time": br.time}


# ---------------------------------------------------------------- sessions, kill zones, Asian range, Judas, AMD

def _us_dst(d: dt.date) -> bool:
    """US daylight saving: 2nd Sunday of March to 1st Sunday of November."""
    def nth_sunday(y, m, n):
        x = dt.date(y, m, 1)
        x += dt.timedelta(days=(6 - x.weekday()) % 7)
        return x + dt.timedelta(days=7 * (n - 1))
    return nth_sunday(d.year, 3, 2) <= d < nth_sunday(d.year, 11, 1)


def kill_zones(market: str, day: dt.date) -> list[dict]:
    """Kill-zone windows (epoch seconds) for a UTC/IST calendar day."""
    def utc(h, m=0, dd=day):
        return int(dt.datetime(dd.year, dd.month, dd.day, h, m, tzinfo=dt.timezone.utc).timestamp())
    if market in ("NSE", "FNO", "BSE"):
        ist = dt.timezone(dt.timedelta(hours=5, minutes=30))
        t = lambda h, m: int(dt.datetime(day.year, day.month, day.day, h, m, tzinfo=ist).timestamp())
        return [{"name": "NSE opening drive", "start": t(9, 15), "end": t(10, 15)},
                {"name": "NSE closing hour", "start": t(14, 30), "end": t(15, 30)}]
    shift = -1 if _us_dst(day) else 0  # New York open is one hour earlier in UTC during US summer time
    return [{"name": "Asian range", "start": utc(0), "end": utc(6)},
            {"name": "London open", "start": utc(7 + shift), "end": utc(10 + shift)},
            {"name": "New York open", "start": utc(12 + shift), "end": utc(15 + shift)},
            {"name": "London close", "start": utc(15 + shift), "end": utc(17 + shift)}]


def session_model(bars: list[Candle], market: str) -> dict:
    """Asian range (or NSE opening range), Judas swing and AMD phase for the latest day in `bars`."""
    if not bars:
        return {}
    india = market in ("NSE", "FNO", "BSE", "MCX")
    tz = dt.timezone(dt.timedelta(hours=5, minutes=30)) if india else dt.timezone.utc
    day = dt.datetime.fromtimestamp(bars[-1].time, tz).date()
    today = [b for b in bars if dt.datetime.fromtimestamp(b.time, tz).date() == day]
    if not today:
        return {}
    zones = kill_zones(market, day)
    if india:
        acc = [b for b in today if b.time < today[0].time + 30 * 60]
        name = "opening 30 minutes"
        kz = zones[0]
    else:
        acc = [b for b in today if zones[0]["start"] <= b.time < zones[0]["end"]]
        name = "Asian range"
        kz = zones[1]
    if not acc:
        return {"day": day.isoformat(), "kill_zones": zones}
    hi, lo = max(b.high for b in acc), min(b.low for b in acc)
    after = [b for b in today if b.time > acc[-1].time]
    manip = dist = None
    for b in after:
        if manip is None:
            if b.high > hi:
                manip = ("up", b.time, b.high)
            elif b.low < lo:
                manip = ("down", b.time, b.low)
        elif dist is None:
            if manip[0] == "up" and b.close < lo:
                dist = ("down", b.time)
            elif manip[0] == "down" and b.close > hi:
                dist = ("up", b.time)
    phase = "distribution" if dist else "manipulation" if manip else "accumulation"
    judas = None
    open_px = today[0].open
    if manip and kz["start"] <= manip[1] < kz["end"]:
        for b in after:
            if b.time <= manip[1]:
                continue
            if (manip[0] == "up" and b.close < open_px) or (manip[0] == "down" and b.close > open_px):
                judas = {"fake_move": manip[0], "extreme": manip[2], "time": manip[1], "confirmed": b.time,
                         "bias": "bearish" if manip[0] == "up" else "bullish"}
                break
    return {"day": day.isoformat(), "range_name": name, "range_high": hi, "range_low": lo, "session_open": open_px,
            "amd_phase": phase, "manipulation": {"side": manip[0], "time": manip[1], "extreme": manip[2]} if manip else None,
            "distribution": {"side": dist[0], "time": dist[1]} if dist else None, "judas": judas, "kill_zones": zones,
            "in_kill_zone": next((z["name"] for z in zones if z["start"] <= bars[-1].time < z["end"]), None)}


def period_levels(daily: list[Candle], now_t: int, tz_ist: bool) -> dict:
    """Previous day / week / month high and low from daily candles (the current period excluded)."""
    tz = dt.timezone(dt.timedelta(hours=5, minutes=30)) if tz_ist else dt.timezone.utc
    if not daily:
        return {}
    today = dt.datetime.fromtimestamp(now_t, tz).date()
    d = [(dt.datetime.fromtimestamp(b.time, tz).date(), b) for b in daily]
    prev_days = [b for day, b in d if day < today]
    out = {}
    if prev_days:
        out.update(pdh=prev_days[-1].high, pdl=prev_days[-1].low, pdc=prev_days[-1].close)
    wk = today.isocalendar()[:2]
    pw = [b for day, b in d if day.isocalendar()[:2] < wk]
    if pw:
        last_wk = max(day.isocalendar()[:2] for day, b in d if day.isocalendar()[:2] < wk)
        w = [b for day, b in d if day.isocalendar()[:2] == last_wk]
        out.update(pwh=max(b.high for b in w), pwl=min(b.low for b in w))
    pm = [(day, b) for day, b in d if (day.year, day.month) < (today.year, today.month)]
    if pm:
        ym = max((day.year, day.month) for day, _ in pm)
        m = [b for day, b in pm if (day.year, day.month) == ym]
        out.update(pmh=max(b.high for b in m), pml=min(b.low for b in m))
    return out


def smt(a_bars: list[Candle], b_bars: list[Candle], a_name: str, b_name: str, span: int = 3, lookback: int = 60) -> list[dict]:
    """SMT divergence over a shared time axis."""
    common = sorted(set(x.time for x in a_bars[-lookback * 2:]) & set(x.time for x in b_bars[-lookback * 2:]))[-lookback:]
    A = {x.time: x for x in a_bars}
    B = {x.time: x for x in b_bars}
    a = [A[t] for t in common]
    b = [B[t] for t in common]
    if len(a) < 2 * span + 3:
        return []
    out = []
    from .ind import pivots
    for kind in ("high", "low"):
        pa = pivots([x.high if kind == "high" else x.low for x in a], span, kind)
        pb = pivots([x.high if kind == "high" else x.low for x in b], span, kind)
        if not pa or not pb:
            continue
        la, lb = a[pa[-1]], b[pb[-1]]
        lvl_a = la.high if kind == "high" else la.low
        lvl_b = lb.high if kind == "high" else lb.low
        start = max(pa[-1], pb[-1]) + span
        for i in range(start + 1, len(a)):
            ta = a[i].high > lvl_a if kind == "high" else a[i].low < lvl_a
            tb = b[i].high > lvl_b if kind == "high" else b[i].low < lvl_b
            if ta != tb:
                leader = a_name if ta else b_name
                lagger = b_name if ta else a_name
                out.append({"direction": "bearish" if kind == "high" else "bullish", "time": common[i],
                            "text": f"{leader} took its previous swing {kind} but {lagger} did not"})
                break
    return out


def inducement(bars: list[Candle], obs: list[OrderBlock], fvgs: list[dict]) -> dict | None:
    """Nearest unmitigated POI below (bullish) / above (bearish) price and the internal swing guarding it."""
    if len(bars) < 10:
        return None
    rep = S.analyze_smc(bars, INTERNAL_SPAN)
    price = bars[-1].close
    pois = [(o.top, o.bottom, "bullish order block") for o in obs if o.direction == "bullish" and o.state == "fresh" and o.top < price]
    pois += [(g["top"], g["bottom"], "bullish FVG") for g in fvgs if g["direction"] == "bullish" and not g["filled_time"] and g["top"] < price]
    if not pois:
        return None
    top, bottom, what = max(pois, key=lambda p: p[0])
    guard = [s for s in rep.swings if s.kind == "low" and top < s.price < price]
    if not guard:
        return {"poi": what, "poi_top": top, "poi_bottom": bottom, "inducement": None}
    g = guard[-1]
    taken = any(b.low < g.price for b in bars if b.time > g.confirmed_time)
    return {"poi": what, "poi_top": top, "poi_bottom": bottom, "inducement": g.price, "inducement_time": g.time, "taken": taken}


def analyze(bars: list[Candle], market: str, daily: list[Candle] | None = None, now_t: int | None = None) -> dict:
    """Everything above for one timeframe."""
    ext = S.analyze_smc(bars, EXTERNAL_SPAN)
    intl = S.analyze_smc(bars, INTERNAL_SPAN)
    obs = order_blocks(bars, ext)
    fv = fvg_extras(bars, ext)
    price = bars[-1].close if bars else None
    return {
        "external": S.smc_payload(ext),
        "internal": {"trend": intl.trend, "structure": [asdict(x) for x in intl.structure[-20:]]},
        "mss": mss(bars, ext)[-10:],
        "protected": protected_levels(ext),
        "order_blocks": [{**asdict(o), "state": o.state} for o in obs[-20:]],
        "fvgs": fv[-25:],
        "equal_levels": equal_levels(bars, ext),
        "dealing_range": dealing_range(ext, price) if price else {},
        "ote": ote(bars, ext),
        "session": session_model(bars, market),
        "period_levels": period_levels(daily or [], now_t or (bars[-1].time if bars else 0), market in ("NSE", "FNO", "BSE", "MCX")),
        "inducement": inducement(bars, obs, fv),
        "_reports": (ext, intl, obs),
    }

backend/lab/options.py:
"""Options and derivatives intelligence.

Indian options come from the FYERS option chain (greeks=1); crypto options from Delta Exchange India; crypto
perpetuals (funding, open interest, basis) from Delta Exchange and Shark where Shark publishes it.

Interpretations are probabilistic, not statements about who holds what:
- Build-up per strike: OI up + premium up = long build-up; OI up + premium down = writing; OI down + premium up =
  short covering; OI down + premium down = long unwinding.
- OI support / resistance: the strikes with the most fresh put (call) writing within ATM +/-6 strikes, else the
  largest put (call) OI there.
- Max pain: the expiry price that minimises the total payout to option holders. Limitation: assumes positions are
  held to expiry and ignores hedges; it is a magnet only in quiet markets.
- GEX (gamma exposure, estimate): sum over strikes of gamma x OI x lot x spot^2 x 1%, calls positive and puts
  negative, i.e. the textbook assumption that dealers are long calls / short puts. Real dealer positioning is
  unknown; treat the sign as a rough guide (positive: moves tend to be dampened, negative: amplified).
- DEX (delta exposure): sum of delta x OI x lot.
- Expected move to expiry: spot x ATM IV x sqrt(days / 365), and the ATM straddle x 0.85 as a market-priced check.
- Skew: OTM put IV minus OTM call IV at about 3% from spot.
- IV rank / percentile: ATM IV against the snapshots this app has recorded (needs at least 20; until then shown as
  "not enough history").
- Rho: FYERS does not send it; it is computed with Black-Scholes from the strike, spot, IV, time and a 6.5% (INR)
  or 0% (crypto) rate.
"""
from __future__ import annotations

import json
import math
import statistics
import time
from typing import Any

from . import store

INDEX_SYMBOLS = {"NIFTY": "NSE:NIFTY50-INDEX", "BANKNIFTY": "NSE:NIFTYBANK-INDEX", "FINNIFTY": "NSE:FINNIFTY-INDEX",
                 "MIDCPNIFTY": "NSE:MIDCPNIFTY-INDEX", "SENSEX": "BSE:SENSEX-INDEX", "BANKEX": "BSE:BANKEX-INDEX"}
LOTS = {"NIFTY": 65, "BANKNIFTY": 30, "FINNIFTY": 65, "MIDCPNIFTY": 120, "SENSEX": 20, "BANKEX": 30}


def _ncdf(x: float) -> float:
    return 0.5 * (1 + math.erf(x / math.sqrt(2)))


def bs_rho(kind: str, s: float, k: float, iv_pct: float, days: float, r: float) -> float | None:
    """Rho per 1 percentage point change in the rate."""
    t = max(days, 1e-4) / 365
    v = (iv_pct or 0) / 100
    if s <= 0 or k <= 0 or v <= 0:
        return None
    d1 = (math.log(s / k) + (r + v * v / 2) * t) / (v * math.sqrt(t))
    d2 = d1 - v * math.sqrt(t)
    rho = k * t * math.exp(-r * t) * (_ncdf(d2) if kind == "CE" else -_ncdf(-d2))
    return rho / 100


def _build(side: str, d_oi: float, d_px: float) -> tuple[str, int] | None:
    if not d_oi:
        return None
    up = d_px > 0
    if d_oi > 0 and up:
        return "Long build-up", 1 if side == "CE" else -1
    if d_oi > 0:
        return ("Call writing", -1) if side == "CE" else ("Put writing", 1)
    if up:
        return "Short covering", 1 if side == "CE" else -1
    return ("Call unwinding", 1) if side == "CE" else ("Put unwinding", -1)


def analyse_chain(rows: list[dict], spot: float, lot: float, days: float, rate: float, coin: bool = False) -> dict:
    """rows: one dict per strike {strike, ce:{...}, pe:{...}} with oi, oi_chg, ltp, ltp_chg, vol, bid, ask, iv, delta,
    gamma, theta, vega."""
    rows = sorted(rows, key=lambda r: r["strike"])
    if not rows or not spot:
        return {"error": "empty chain"}
    ks = [r["strike"] for r in rows]
    ai = min(range(len(ks)), key=lambda i: abs(ks[i] - spot))
    leg = lambda r, s: r.get(s) or {}
    tot = {s: sum(leg(r, s).get("oi", 0) or 0 for r in rows) for s in ("ce", "pe")}
    vol = {s: sum(leg(r, s).get("vol", 0) or 0 for r in rows) for s in ("ce", "pe")}
    pain = min(ks, key=lambda x: sum((leg(r, "ce").get("oi", 0) or 0) * max(0, x - r["strike"]) +
                                     (leg(r, "pe").get("oi", 0) or 0) * max(0, r["strike"] - x) for r in rows))
    band = rows[max(0, ai - 6): ai + 7]
    below = [r for r in band if r["strike"] <= spot] or band
    above = [r for r in band if r["strike"] >= spot] or band
    pick = lambda arr, s: (max((r for r in arr if (leg(r, s).get("oi_chg") or 0) > 0), key=lambda r: leg(r, s)["oi_chg"], default=None)
                           or max(arr, key=lambda r: leg(r, s).get("oi", 0) or 0))
    sup, res = pick(below, "pe"), pick(above, "ce")
    chg_all = [abs(leg(r, s).get("oi_chg") or 0) for r in rows for s in ("ce", "pe") if leg(r, s)]
    med = statistics.median(chg_all) if chg_all else 0
    unusual, strikes_out, gex, dex, bull_w, bear_w = [], [], 0.0, 0.0, 0.0, 0.0
    for r in rows:
        out = {"strike": r["strike"]}
        for s, sign in (("ce", 1), ("pe", -1)):
            o = leg(r, s)
            if not o:
                continue
            g, dlt = o.get("gamma") or 0, o.get("delta") or 0
            gex += sign * g * (o.get("oi") or 0) * lot * spot * spot * 0.01
            dex += dlt * (o.get("oi") or 0) * lot
            b = _build(s.upper(), o.get("oi_chg") or 0, o.get("ltp_chg") or 0)
            if b and abs(r["strike"] - spot) <= 8 * (ks[1] - ks[0] if len(ks) > 1 else 1):
                if b[1] > 0:
                    bull_w += abs(o.get("oi_chg") or 0)
                else:
                    bear_w += abs(o.get("oi_chg") or 0)
            spread = (o.get("ask") or 0) - (o.get("bid") or 0) if o.get("ask") and o.get("bid") else None
            rho = bs_rho(s.upper(), spot, r["strike"], o.get("iv") or 0, days, rate)
            out[s] = {**{k: o.get(k) for k in ("oi", "oi_chg", "ltp", "ltp_chg", "vol", "iv", "delta", "gamma", "theta", "vega", "symbol")},
                      "rho": round(rho, 4) if rho is not None else None, "spread": spread, "build_up": b[0] if b else None}
            if med and abs(o.get("oi_chg") or 0) >= 3 * med and abs(o.get("oi_chg") or 0) > 0:
                unusual.append({"strike": r["strike"], "side": s.upper(), "oi_chg": o.get("oi_chg"), "times_median": round(abs(o["oi_chg"]) / med, 1)})
        strikes_out.append(out)
    atm = rows[ai]
    ivs = [x for x in (leg(atm, "ce").get("iv"), leg(atm, "pe").get("iv")) if x]
    atm_iv = sum(ivs) / len(ivs) if ivs else None
    straddle = (leg(atm, "ce").get("ltp") or 0) + (leg(atm, "pe").get("ltp") or 0)
    em = spot * atm_iv / 100 * math.sqrt(max(days, 1 / 24) / 365) if atm_iv else None
    put_k = min(ks, key=lambda k: abs(k - spot * 0.97))
    call_k = min(ks, key=lambda k: abs(k - spot * 1.03))
    piv = leg(next(r for r in rows if r["strike"] == put_k), "pe").get("iv")
    civ = leg(next(r for r in rows if r["strike"] == call_k), "ce").get("iv")
    flow = round(100 * (bull_w - bear_w) / (bull_w + bear_w)) if bull_w + bear_w else 0
    return {"spot": spot, "atm": atm["strike"], "days": round(days, 2), "pcr_oi": tot["pe"] / tot["ce"] if tot["ce"] else None,
            "pcr_vol": vol["pe"] / vol["ce"] if vol["ce"] else None, "oi_ce": tot["ce"], "oi_pe": tot["pe"], "max_pain": pain,
            "max_pain_note": "Assumes positions are held to expiry; a magnet mainly in quiet markets.",
            "oi_support": sup["strike"], "oi_resistance": res["strike"], "oi_flow": flow,
            "gex_est": gex, "gex_note": "Estimate: assumes dealers long calls / short puts. Positive = moves damped, negative = amplified.",
            "dex": dex, "atm_iv": atm_iv, "straddle": straddle, "expected_move_iv": em,
            "expected_move_straddle": straddle * 0.85 if straddle else None,
            "skew_put_minus_call": (piv - civ) if piv and civ else None, "unusual_oi": sorted(unusual, key=lambda u: -abs(u["oi_chg"]))[:8],
            "strikes": strikes_out}


async def india_chain(underlying: str, expiry: str = "wk", strikes: int = 15) -> dict:
    from backend.brokers.fyers.client import data_get
    sym = INDEX_SYMBOLS.get(underlying.upper(), underlying)
    first = await data_get("/options-chain-v3", {"symbol": sym, "strikecount": strikes, "timestamp": "", "greeks": "1"})
    d = first.get("data") or first
    exps = sorted(d.get("expiryData") or [], key=lambda e: int(e.get("expiry") or 0))
    if not exps:
        return {"error": f"FYERS returned no expiries for {underlying}"}
    pick = exps[0] if expiry == "wk" else next((e for e in exps if e.get("expiry_flag") == "M"), exps[0])
    if pick is not exps[0]:
        d = (await data_get("/options-chain-v3", {"symbol": sym, "strikecount": strikes, "timestamp": str(pick["expiry"]), "greeks": "1"})).get("data") or {}
    chain = d.get("optionsChain") or []
    spot = next((float(r.get("ltp") or 0) for r in chain if float(r.get("strike_price") or 0) <= 0), 0.0)
    by: dict[float, dict] = {}
    for r in chain:
        if r.get("option_type") not in ("CE", "PE"):
            continue
        g = r.get("greeks") or {}
        by.setdefault(float(r["strike_price"]), {"strike": float(r["strike_price"])})[r["option_type"].lower()] = {
            "oi": float(r.get("oi") or 0), "oi_chg": float(r.get("oich") or 0), "ltp": float(r.get("ltp") or 0),
            "ltp_chg": float(r.get("ltpch") or 0), "vol": float(r.get("volume") or 0), "bid": float(r.get("bid") or 0),
            "ask": float(r.get("ask") or 0), "iv": float(g.get("iv") or 0), "delta": float(g.get("delta") or 0),
            "gamma": float(g.get("gamma") or 0), "theta": float(g.get("theta") or 0), "vega": float(g.get("vega") or 0),
            "symbol": r.get("symbol")}
    days = max(0.0, (int(pick["expiry"]) + 10 * 3600 - time.time()) / 86400)
    out = analyse_chain(list(by.values()), spot, LOTS.get(underlying.upper(), 1), days, 0.065)
    out.update(underlying=underlying.upper(), expiry=pick.get("date"), source="FYERS option chain", as_of=int(time.time()),
               vix=float((d.get("indiavixData") or {}).get("ltp") or 0) or None)
    out.update(iv_rank=iv_rank(underlying.upper(), out.get("atm_iv")))
    return out


async def crypto_chain(coin: str, expiry: str | None = None) -> dict:
    from backend.markets.crypto_dash import options as delta_options
    ch = await delta_options(coin.upper(), expiry, 25)
    rows = []
    for s in ch["strikes"]:
        r = {"strike": s["strike"]}
        for side in ("ce", "pe"):
            o = s.get(side)
            if o:
                oi_coins = o.get("oi") or 0
                per = (o.get("oi_usd") / oi_coins) if oi_coins and o.get("oi_usd") else ch["spot"]
                r[side] = {"oi": oi_coins, "oi_chg": (o.get("oi_chg6h_usd") or 0) / per if per else 0, "ltp": o.get("mark") or 0,
                           "ltp_chg": o.get("mark_chg24h") or 0, "vol": 0, "iv": o.get("iv") or 0, "delta": o.get("delta") or 0,
                           "gamma": o.get("gamma") or 0, "theta": o.get("theta") or 0, "vega": 0, "symbol": o.get("symbol")}
        rows.append(r)
    out = analyse_chain(rows, ch["spot"], 1.0, ch["days"], 0.0, True)
    out.update(underlying=coin.upper(), expiry=ch["expiry"], source="Delta Exchange India options (OI change = 6 hours)",
               as_of=int(time.time()), iv_rank=iv_rank(coin.upper(), out.get("atm_iv")))
    return out


async def crypto_derivs(pair: str) -> dict:
    """Funding, open interest and basis for a perpetual. Shark first for its own price; Delta for funding/OI/basis
    (Shark does not publish them on its public API)."""
    from backend.markets.crypto import DELTA
    base = pair.upper().replace("USDT", "").replace("INR", "").replace("USD", "")
    out: dict[str, Any] = {"pair": pair, "source": "Delta Exchange India"}
    try:
        r = (await DELTA._get(f"/v2/tickers/{base}USD")).get("result") or {}
        mark, spot = float(r.get("mark_price") or 0), float(r.get("spot_price") or 0)
        out.update(mark=mark, spot=spot, basis_pct=(mark / spot - 1) * 100 if mark and spot else None,
                   funding_rate_pct=float(r.get("funding_rate") or 0) if r.get("funding_rate") is not None else None,
                   oi_contracts=float(r.get("oi_contracts") or r.get("oi") or 0), oi_usd=float(r.get("oi_value_usd") or 0) or None,
                   oi_change_usd_6h=float(r.get("oi_change_usd_6h") or 0) if r.get("oi_change_usd_6h") is not None else None)
    except Exception as exc:                          # noqa: BLE001
        out["error"] = f"Delta derivatives data unavailable: {str(getattr(exc, 'detail', exc))[:120]}"
    return out


def liquidation_estimates(price: float, swing_low: float | None, swing_high: float | None) -> dict:
    """Where leveraged positions opened near recent swings would be liquidated (isolated margin, ~0.5% maintenance).
    These are estimates from arithmetic, not exchange liquidation data (exchanges do not publish it)."""
    out = {"note": "Estimated from leverage arithmetic around recent swings; not exchange liquidation data."}
    for lev in (10, 25, 50):
        m = 1 / lev - 0.005
        if swing_low:
            out[f"long_{lev}x"] = swing_low * (1 - m)
        if swing_high:
            out[f"short_{lev}x"] = swing_high * (1 + m)
    return out


def iv_rank(underlying: str, atm_iv: float | None) -> dict:
    if not atm_iv:
        return {"available": False}
    hist = [r["atm_iv"] for r in store.q("SELECT atm_iv FROM chain_snapshots WHERE underlying=? AND atm_iv>0 ORDER BY t DESC LIMIT 2000", (underlying,))]
    if len(hist) < 20:
        return {"available": False, "note": f"needs 20+ recorded snapshots (have {len(hist)}); the recorder adds one every 15 minutes"}
    lo, hi = min(hist), max(hist)
    return {"available": True, "rank": round(100 * (atm_iv - lo) / (hi - lo), 1) if hi > lo else 50.0,
            "percentile": round(100 * sum(1 for x in hist if x < atm_iv) / len(hist), 1), "samples": len(hist)}


def save_snapshot(ch: dict) -> None:
    if ch.get("error"):
        return
    store.execute("INSERT OR REPLACE INTO chain_snapshots VALUES (?,?,?,?,?,?,?)",
                  (ch["underlying"], int(time.time()), ch.get("expiry"), ch.get("spot"), ch.get("atm_iv") or 0,
                   ch.get("pcr_oi") or 0, json.dumps({k: v for k, v in ch.items() if k != "strikes"})))


def history_trends(underlying: str, hours: float = 6) -> dict:
    """PCR and ATM IV change over the recorded snapshots (for PCR divergence and IV expansion/contraction)."""
    rows = store.q("SELECT t, spot, atm_iv, pcr FROM chain_snapshots WHERE underlying=? AND t>=? ORDER BY t",
                   (underlying, int(time.time() - hours * 3600)))
    if len(rows) < 2:
        return {"available": False}
    a, b = rows[0], rows[-1]
    out = {"available": True, "from": a["t"], "to": b["t"], "pcr_change": b["pcr"] - a["pcr"],
           "iv_change": b["atm_iv"] - a["atm_iv"], "spot_change_pct": (b["spot"] / a["spot"] - 1) * 100 if a["spot"] else None}
    if out["spot_change_pct"] is not None:
        if out["pcr_change"] > 0.1 and out["spot_change_pct"] < -0.2:
            out["pcr_divergence"] = "PCR rising while price falls: puts being written into weakness (possible support)"
        elif out["pcr_change"] < -0.1 and out["spot_change_pct"] > 0.2:
            out["pcr_divergence"] = "PCR falling while price rises: calls being written into strength (possible cap)"
    out["iv_state"] = "expanding" if out["iv_change"] > 1 else "contracting" if out["iv_change"] < -1 else "stable"
    return out

backend/lab/pa.py:
"""Price action engine: candle patterns, candle strength, volatility contraction/expansion, support/resistance and
supply/demand zones, breakout-retest and false breakouts, ranges and trend exhaustion. Patterns are reported with
their context (where they formed) instead of as stand-alone signals. Closed candles only.

Definitions (ATR = Wilder ATR14 at that candle)
- Bullish engulfing: previous candle red, this candle green, body covers the previous body. Bearish mirror.
- Pin bar: one wick >= 2 x body and >= 60% of the range, the other wick <= 25% of the range. Hammer = lower wick
  (bullish rejection), shooting star = upper wick (bearish rejection).
- Rejection candle: a pin bar whose long wick traded through a support/resistance zone or a swing level and
  closed back inside.
- Inside bar: high <= previous high and low >= previous low. Outside bar: high > previous high and low < previous low.
- Momentum candle: body >= 1 x ATR and closes in the outer 25% of its range. Displacement: see ict.py.
- Consecutive strength: the run of same-colour candles ending at the latest candle, with their summed body / ATR.
- Range expansion: range >= 1.5 x ATR. Volume expansion: volume >= 1.5 x the 20-candle average.
- Volatility contraction: Bollinger bandwidth in the lowest 20% of its last 120 values (squeeze); expansion when
  the latest bandwidth exceeds the 80th percentile.
- S/R zones: confirmed swing highs/lows (span 3) clustered within 0.25 x ATR, scored by touches; a zone the last
  close is above is support, below is resistance.
- Supply/demand: the base candle(s) before a displacement candle; zone = base low..high.
- Breakout + retest: a close beyond a zone, then within 10 candles a candle touches the zone and closes back on the
  breakout side.
- False breakout: from smc.py traps (close beyond a structure level reversed within 3 candles).
- Range-bound: ADX < 20 and the last 30 candles' high-low range < 4 x ATR.
- Trend exhaustion: 3+ consecutive momentum candles in one direction ending at an RSI extreme (>75 / <25), or a
  regular RSI divergence at the latest pivot.
"""
from __future__ import annotations

from .candle import Candle
from .ind import atr_list, bollinger, sma, rsi, adx_dmi, pivots, divergences


def candle_patterns(bars: list[Candle], lookback: int = 30) -> list[dict]:
    a = atr_list(bars)
    vavg = sma([b.volume for b in bars], 20)
    out = []
    for i in range(max(1, len(bars) - lookback), len(bars)):
        b, p = bars[i], bars[i - 1]
        rng = b.high - b.low
        if rng <= 0:
            continue
        body = abs(b.close - b.open)
        up_w = b.high - max(b.open, b.close)
        lo_w = min(b.open, b.close) - b.low
        green, pgreen = b.close > b.open, p.close > p.open
        tags = []
        if green and not pgreen and b.close >= p.open and b.open <= p.close and body > abs(p.close - p.open):
            tags.append(("bullish engulfing", "bullish"))
        if not green and pgreen and b.close <= p.open and b.open >= p.close and body > abs(p.close - p.open):
            tags.append(("bearish engulfing", "bearish"))
        if lo_w >= 2 * body and lo_w >= 0.6 * rng and up_w <= 0.25 * rng:
            tags.append(("hammer / bullish pin bar", "bullish"))
        if up_w >= 2 * body and up_w >= 0.6 * rng and lo_w <= 0.25 * rng:
            tags.append(("shooting star / bearish pin bar", "bearish"))
        if b.high <= p.high and b.low >= p.low:
            tags.append(("inside bar", "neutral"))
        if b.high > p.high and b.low < p.low:
            tags.append(("outside bar", "bullish" if green else "bearish"))
        if a[i] and body >= a[i] and ((green and b.close >= b.high - 0.25 * rng) or (not green and b.close <= b.low + 0.25 * rng)):
            tags.append(("momentum candle", "bullish" if green else "bearish"))
        if a[i] and rng >= 1.5 * a[i]:
            tags.append(("range expansion", "bullish" if green else "bearish"))
        if vavg[i] and b.volume >= 1.5 * vavg[i]:
            tags.append(("volume expansion", "bullish" if green else "bearish"))
        for name, d in tags:
            out.append({"time": b.time, "pattern": name, "direction": d, "wick_body_ratio": round((up_w + lo_w) / body, 2) if body else None})
    return out


def consecutive(bars: list[Candle]) -> dict:
    a = atr_list(bars)
    if not bars:
        return {}
    green = bars[-1].close > bars[-1].open
    n, body = 0, 0.0
    for b in reversed(bars):
        if (b.close > b.open) != green or b.close == b.open:
            break
        n += 1
        body += abs(b.close - b.open)
    at = next((x for x in reversed(a) if x), None)
    return {"direction": "bullish" if green else "bearish", "count": n, "body_atr": round(body / at, 2) if at else None}


def volatility_state(bars: list[Candle]) -> dict:
    _, _, _, bw = bollinger([b.close for b in bars])
    hist = [x for x in bw[-120:] if x is not None]
    if len(hist) < 30:
        return {"state": "unknown"}
    cur = hist[-1]
    rank = 100 * sum(1 for x in hist if x < cur) / len(hist)
    state = "contraction (squeeze)" if rank <= 20 else "expansion" if rank >= 80 else "normal"
    return {"state": state, "bandwidth_pct": round(cur, 3), "bandwidth_rank": round(rank)}


def sr_zones(bars: list[Candle], span: int = 3, max_zones: int = 8) -> list[dict]:
    a = atr_list(bars)
    at = next((x for x in reversed(a) if x), None)
    if not at or len(bars) < 2 * span + 1:
        return []
    pts = [(bars[j].high, bars[j].time) for j in pivots([b.high for b in bars], span, "high")]
    pts += [(bars[j].low, bars[j].time) for j in pivots([b.low for b in bars], span, "low")]
    pts.sort()
    zones = []
    for px, t in pts:
        if zones and px - zones[-1]["top"] <= 0.25 * at:
            z = zones[-1]
            z["top"] = max(z["top"], px)
            z["touches"] += 1
            z["last_time"] = max(z["last_time"], t)
        else:
            zones.append({"bottom": px, "top": px, "touches": 1, "last_time": t})
    last = bars[-1].close
    for z in zones:
        z["kind"] = "support" if last > z["top"] else "resistance" if last < z["bottom"] else "inside"
        z["mid"] = (z["top"] + z["bottom"]) / 2
    zones.sort(key=lambda z: (-z["touches"], abs(z["mid"] - last)))
    return sorted(zones[:max_zones], key=lambda z: z["mid"])


def supply_demand(bars: list[Candle], disp: list[int], lookback: int = 150) -> list[dict]:
    out = []
    for i in range(max(1, len(bars) - lookback), len(bars)):
        if disp[i] == 0:
            continue
        base = bars[i - 1]
        z = {"kind": "demand" if disp[i] > 0 else "supply", "top": base.high, "bottom": base.low, "time": base.time, "fresh": True}
        for b in bars[i + 1:]:
            if b.low <= z["top"] and b.high >= z["bottom"]:
                z["fresh"] = False
                break
        out.append(z)
    return out[-10:]


def breakout_retest(bars: list[Candle], zones: list[dict], window: int = 10) -> list[dict]:
    out = []
    for z in zones:
        for i in range(len(bars) - 60 if len(bars) > 60 else 1, len(bars)):
            b, p = bars[i], bars[i - 1]
            up = p.close <= z["top"] < b.close
            dn = p.close >= z["bottom"] > b.close
            if not (up or dn):
                continue
            for j in range(i + 1, min(len(bars), i + 1 + window)):
                c = bars[j]
                if up and c.low <= z["top"] and c.close > z["top"]:
                    out.append({"direction": "bullish", "level": z["top"], "break_time": b.time, "retest_time": c.time})
                    break
                if dn and c.high >= z["bottom"] and c.close < z["bottom"]:
                    out.append({"direction": "bearish", "level": z["bottom"], "break_time": b.time, "retest_time": c.time})
                    break
    return sorted(out, key=lambda x: x["retest_time"])[-6:]


def range_and_exhaustion(bars: list[Candle]) -> dict:
    a = atr_list(bars)
    adx, _, _ = adx_dmi(bars)
    r = rsi([b.close for b in bars])
    at = next((x for x in reversed(a) if x), None)
    w = bars[-30:]
    out = {}
    if at and adx[-1] is not None and len(w) == 30:
        span = max(b.high for b in w) - min(b.low for b in w)
        out["range_bound"] = adx[-1] < 20 and span < 4 * at
        out["range_high"], out["range_low"] = max(b.high for b in w), min(b.low for b in w)
    c = consecutive(bars)
    exh = None
    if c.get("count", 0) >= 3 and r[-1] is not None and ((c["direction"] == "bullish" and r[-1] > 75) or (c["direction"] == "bearish" and r[-1] < 25)):
        exh = f"{c['count']} {c['direction']} candles into RSI {r[-1]:.0f}"
    dv = [d for d in divergences(bars, r, "RSI") if d["type"] == "regular"]
    if dv and dv[-1]["to"] >= bars[max(0, len(bars) - 10)].time:
        exh = (exh + "; " if exh else "") + f"regular {dv[-1]['direction']} RSI divergence"
    out["exhaustion"] = exh
    return out


def analyze(bars: list[Candle], disp: list[int], traps: list[dict]) -> dict:
    zones = sr_zones(bars)
    return {"patterns": candle_patterns(bars)[-15:], "consecutive": consecutive(bars), "volatility": volatility_state(bars),
            "zones": zones, "supply_demand": supply_demand(bars, disp), "breakout_retest": breakout_retest(bars, zones),
            "false_breakouts": traps[-5:], **range_and_exhaustion(bars)}

backend/lab/protect.py:
"""Capital protection for PAPER trades (the lab never places real orders).

Rules (all settings, stored in the settings table under "protection"):
  capital              paper capital per currency (INR for India, USD for crypto/US)
  risk_pct             risk per trade as % of capital (default 0.5)
  daily_loss_pct       stop opening trades for the day after this loss (default 2)
  weekly_loss_pct      stop for the week (default 5)
  max_open             maximum open paper trades (default 3)
  max_correlated       maximum open trades in one correlation group (default 2); groups below
  loss_streak_lockout  consecutive losses that lock new trades until the next day (default 3)
  cooldown_min         minutes after a losing trade before the same symbol can be traded again (default 30) -
                       blocks revenge trading
  no averaging         a second trade in the same symbol and direction while one is open is refused
  min_score            minimum setup score for a paper trade (default 60)
  unlimited_trades     (default ON, user rule 2026-11-10) no trade-count / lockout rules: max_open, max_correlated, daily and
                       weekly loss limits, loss-streak lockout and cooldown are switched off. The only capacity limit is
                       the capital allocated per day (day_capital_inr / day_capital_usd): capital in open paper trades
                       (qty x entry) + the new trade <= that amount, so closed trades free capital and trades are unlimited.
                       Score, risk sizing per trade and "no averaging" still apply.
Position size = risk amount / per-unit risk (entry - stop), rounded DOWN to the lot size; if that is zero the trade
is refused (the stop is too wide for the risk budget).
"""
from __future__ import annotations

import datetime as dt
import math

from . import store

DEFAULTS = {"capital_inr": 500000.0, "capital_usd": 10000.0, "risk_pct": 0.5, "daily_loss_pct": 2.0, "weekly_loss_pct": 5.0,
            "max_open": 3, "max_correlated": 2, "loss_streak_lockout": 3, "cooldown_min": 30, "min_score": 60,
            "unlimited_trades": True, "day_capital_inr": 200000.0, "day_capital_usd": 2500.0}
GROUPS = {
    "india_index": ["NIFTY", "BANKNIFTY", "FINNIFTY", "MIDCPNIFTY", "SENSEX", "BANKEX", "NIFTYBANK", "NIFTY50"],
    "crypto_majors": ["BTC", "ETH", "SOL", "BNB", "XRP", "DOGE", "ADA", "AVAX", "LINK", "LTC"],
    "us_index": ["^GSPC", "^NDX", "^IXIC", "^DJI", "SPY", "QQQ", "^RUT"],
    "energy": ["CRUDEOIL", "NATURALGAS", "CL=F", "NG=F"],
    "metals": ["GOLD", "SILVER", "GC=F", "SI=F", "XAU", "PAXG"],
}
IST = dt.timezone(dt.timedelta(hours=5, minutes=30))


def settings() -> dict:
    return {**DEFAULTS, **(store.get_setting("protection") or {})}


def currency(market: str) -> str:
    return "INR" if market in ("NSE", "FNO", "MCX") else "USD"


def group_of(symbol: str) -> str:
    s = symbol.upper().split(":", 1)[-1]
    for g, names in GROUPS.items():
        if any(n in s for n in names):
            return g
    return "single:" + s


def lot_of(symbol: str) -> float:
    from .options import LOTS
    s = symbol.upper().split(":", 1)[-1]
    for k in sorted(LOTS, key=len, reverse=True):
        if s.startswith(k) and not s.endswith("-INDEX"):
            return LOTS[k]
    return 1.0


def size(symbol: str, market: str, entry: float, stop: float, cfg: dict | None = None) -> dict:
    c = cfg or settings()
    cap = c["capital_inr"] if currency(market) == "INR" else c["capital_usd"]
    risk_amt = cap * c["risk_pct"] / 100
    per = abs(entry - stop)
    if per <= 0:
        return {"qty": 0, "why": "zero risk per unit"}
    lot = lot_of(symbol)
    if market in ("SHARK", "DELTAF", "DELTA", "BINANCE", "YF") and lot == 1:
        q = math.floor(risk_amt / per * 1e4) / 1e4
    else:
        q = math.floor(risk_amt / per / lot) * lot
    if q <= 0:
        return {"qty": 0, "why": f"one lot ({lot:g}) risks {per * lot:,.0f} {currency(market)}, more than the {risk_amt:,.0f} budget"}
    return {"qty": q, "lot": lot, "risk_amount": round(q * per, 2), "budget": risk_amt, "currency": currency(market)}


def _day_start(now: int) -> int:
    d = dt.datetime.fromtimestamp(now, IST)
    return int(dt.datetime(d.year, d.month, d.day, tzinfo=IST).timestamp())


def day_capital(cur: str, c: dict | None = None) -> float:
    c = c or settings()
    return float(c["day_capital_inr"] if cur == "INR" else c["day_capital_usd"])


def capital_in_use(cur: str) -> float:
    return sum(abs((t["qty"] or 0) * (t["entry"] or 0)) for t in store.q("SELECT qty, entry FROM trades WHERE status='open' AND currency=?", (cur,)))


def check(symbol: str, market: str, direction: str, score: float, now: int | None = None, new_capital: float = 0.0) -> dict:
    """May a new paper trade be opened? Returns {ok, blocks: [...], warnings: [...]}."""
    c = settings()
    now = now or store.now()
    cur = currency(market)
    cap = c["capital_inr"] if cur == "INR" else c["capital_usd"]
    blocks = []
    if score < c["min_score"]:
        blocks.append(f"Score {score:.0f} is below the minimum {c['min_score']}")
    open_ = store.q("SELECT * FROM trades WHERE status='open'")
    if c.get("unlimited_trades", True):
        if any(t["symbol"] == symbol and t["side"] == direction for t in open_):
            blocks.append("Already in this symbol and direction: averaging is not allowed")
        used, dc = capital_in_use(cur), day_capital(cur, c)
        if used + new_capital > dc + 1e-6:
            blocks.append(f"Day capital: {used:,.0f} in open trades + {new_capital:,.0f} new > {dc:,.0f} {cur} allocated per day")
        d0 = _day_start(now)
        w0 = d0 - dt.datetime.fromtimestamp(now, IST).weekday() * 86400
        dl = sum(t["pnl"] or 0 for t in store.q("SELECT pnl FROM trades WHERE status='closed' AND closed_at>=? AND currency=?", (d0, cur)))
        wl = sum(t["pnl"] or 0 for t in store.q("SELECT pnl FROM trades WHERE status='closed' AND closed_at>=? AND currency=?", (w0, cur)))
        return {"ok": not blocks, "blocks": blocks, "daily_pnl": dl, "weekly_pnl": wl, "open": len(open_), "loss_streak": 0, "currency": cur,
                "unlimited": True, "capital_used": used, "day_capital": dc}
    if len(open_) >= c["max_open"]:
        blocks.append(f"{len(open_)} trades already open (limit {c['max_open']})")
    if any(t["symbol"] == symbol and t["side"] == direction for t in open_):
        blocks.append("Already in this symbol and direction: averaging is not allowed")
    g = group_of(symbol)
    same = [t for t in open_ if group_of(t["symbol"]) == g]
    if not g.startswith("single:") and len(same) >= c["max_correlated"]:
        blocks.append(f"{len(same)} open trades in the correlated group {g} (limit {c['max_correlated']})")
    d0 = _day_start(now)
    w0 = d0 - dt.datetime.fromtimestamp(now, IST).weekday() * 86400
    day = store.q("SELECT pnl FROM trades WHERE status='closed' AND closed_at>=? AND currency=?", (d0, cur))
    week = store.q("SELECT pnl FROM trades WHERE status='closed' AND closed_at>=? AND currency=?", (w0, cur))
    dl, wl = sum(t["pnl"] or 0 for t in day), sum(t["pnl"] or 0 for t in week)
    if dl <= -cap * c["daily_loss_pct"] / 100:
        blocks.append(f"Daily loss limit hit ({dl:,.0f} {cur})")
    if wl <= -cap * c["weekly_loss_pct"] / 100:
        blocks.append(f"Weekly loss limit hit ({wl:,.0f} {cur})")
    recent = store.q("SELECT pnl, closed_at, symbol FROM trades WHERE status='closed' ORDER BY closed_at DESC LIMIT 20")
    streak = 0
    for t in recent:
        if (t["pnl"] or 0) < 0:
            streak += 1
        else:
            break
    if streak >= c["loss_streak_lockout"] and recent and recent[0]["closed_at"] >= d0:
        blocks.append(f"{streak} losses in a row: locked until tomorrow")
    last_loss = next((t for t in recent if t["symbol"] == symbol and (t["pnl"] or 0) < 0), None)
    if last_loss and now - last_loss["closed_at"] < c["cooldown_min"] * 60:
        blocks.append(f"Cooldown: last {symbol} trade lost {int((now - last_loss['closed_at']) / 60)} min ago (wait {c['cooldown_min']} min)")
    return {"ok": not blocks, "blocks": blocks, "daily_pnl": dl, "weekly_pnl": wl, "open": len(open_), "loss_streak": streak, "currency": cur}

backend/lab/service.py:
"""Signal Lab operations without any web framework. The PC's FastAPI routes (routes.py) and the phone build
(mobile_api.py running in the browser with Pyodide) both call these, so the two versions run the same logic."""
from __future__ import annotations

import asyncio
import json

from .candle import TF_SECONDS
from . import data as D
from . import store
from . import strategies as ST
from . import protect as P
from . import costs as C
from . import paper
from . import recorder
from . import analysis as A
from . import backtest as B
from .engine import Engine, MTF


class BadRequest(Exception):
    def __init__(self, status: int, msg: str):
        super().__init__(msg)
        self.status = status


WATCH = {
    "India": ["NSE:NIFTY50-INDEX", "NSE:NIFTYBANK-INDEX", "NSE:FINNIFTY-INDEX", "BSE:SENSEX-INDEX", "NSE:NIFTY-FUT", "NSE:BANKNIFTY-FUT",
              "NSE:RELIANCE-EQ", "NSE:HDFCBANK-EQ", "NSE:SBIN-EQ", "MCX:CRUDEOIL-FUT", "MCX:GOLD-FUT"],
    "Crypto": ["SHARK:BTCUSDT", "SHARK:ETHUSDT", "SHARK:SOLUSDT", "SHARK:XRPUSDT", "SHARK:BNBUSDT", "SHARK:DOGEUSDT", "DELTAF:BTCUSD", "DELTAF:ETHUSD", "BINANCE:BTCUSDT"],
    "US / Global": ["YF:^GSPC", "YF:^NDX", "YF:^DJI", "YF:SPY", "YF:QQQ", "YF:AAPL", "YF:NVDA", "YF:^N225", "YF:^FTSE", "YF:GC=F", "YF:CL=F"],
    "Forex": ["YF:EURUSD=X", "YF:USDJPY=X", "YF:GBPUSD=X", "YF:USDINR=X", "YF:DX-Y.NYB"],
}
ALL_CRYPTO = "Crypto · all (Shark)"


async def refresh_crypto_universe() -> int:
    """Every live Shark USDT perpetual as its own watch-list group (for the market picker). Returns how many."""
    from backend.markets.crypto import SHARK
    info = await SHARK.load_info(force=True)
    pairs = sorted(p for p, v in info.items() if str(v.get("quote", "")).upper() == "USDT")
    if pairs:
        WATCH[ALL_CRYPTO] = [f"SHARK:{p}" for p in pairs]
    return len(pairs)


async def crypto_universe_loop() -> None:
    import asyncio
    while True:
        try:
            await refresh_crypto_universe()
        except Exception:                                 # noqa: BLE001 - the curated list still works
            pass
        await asyncio.sleep(3600)


PLATFORM = {"name": "pc", "threads": True}             # the phone build sets name="mobile", threads=False


def meta() -> dict:
    return {"timeframes": list(TF_SECONDS), "mtf": MTF, "watch": WATCH, "user_watch": store.get_setting("watch") or [],
            "strategies": {k: {"name": v[0], "description": v[1], "params": {**ST.PARAMS[k], **((store.get_setting("strategies") or {}).get(k) or {})}}
                           for k, v in ST.META.items()},
            "protection": P.settings(), "recorder": recorder.settings(), "costs": {**C.DEFAULTS, **(store.get_setting("costs") or {})},
            "paper_only": True, "platform": PLATFORM["name"]}


def _sym(s: str) -> str:
    s = (s or "").strip()
    if not 3 <= len(s) <= 60:
        raise BadRequest(422, "symbol must be 3-60 characters, e.g. NSE:NIFTY50-INDEX")
    return s


def _tf(tf: str) -> str:
    if tf not in TF_SECONDS:
        raise BadRequest(400, f"timeframe must be one of {', '.join(TF_SECONDS)}")
    return tf


async def analyze(symbol: str, tf: str = "15m", bars: int = 600, fresh: bool = False, live: bool = False) -> dict:
    return await A.analyze(_sym(symbol), _tf(tf), max(200, min(2000, int(bars))), bool(fresh), bool(live))


