def protection(symbol: str = "NSE:NIFTY50-INDEX", direction: str = "LONG") -> dict:
    return {"settings": P.settings(), "status": P.check(symbol, D.market_of(symbol), direction, 100)}


def alerts(unseen: bool = False) -> list:
