def _strikes(ex: str, und: str) -> list[str]:
    """ATM and 4 strikes either side, calls and puts, lowest strike first: NSE:NIFTY-ATMD4-CE ... NSE:NIFTY-ATMU4-PE."""
    out = []
    for k in range(-4, 5):
        a = "ATM" if k == 0 else "ATM" + ("U" if k > 0 else "D") + str(abs(k))
        out += [f"{ex}:{und}-{a}-CE", f"{ex}:{und}-{a}-PE"]
    return out


